{"command": "mkdir -p /tmp/tools && cat > /tmp/tools/blockinfo.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

int main(int argc, char **argv) {
    static unsigned char in[1<<20], out[1<<20];
    size_t n; z_stream s; int ret, blk = 0;
    unsigned long intot = 0, outtot = 0;
    FILE *f = stdin;
    if (argc > 1) f = fopen(argv[1], "rb");
    memset(&s, 0, sizeof(s));
    ret = inflateInit2(&s, argc>1? -15 : 15+16);
    if (ret != Z_OK) { fprintf(stderr, "init %d\n", ret); return 1; }
    s.next_in = in; s.avail_in = 0;
    while (1) {
        size_t pos_in = n - s.avail_in;
        if (s.avail_in == 0 && !feof(f)) {
            n = fread(in, 1, sizeof(in), f);
            s.next_in = in; s.avail_in = (uInt)n;
        }
        s.next_out = out; s.avail_out = sizeof(out);
        ret = inflate(&s, Z_BLOCK);
        size_t prod = sizeof(out) - s.avail_out;
        int last = (s.data_type & 128) >> 7;
        int type = s.data_type & 7;
        printf("block %d: in_bits=%lu in_bytes=%lu out=%lu last=%d type=%d\n",
               blk++, (unsigned long)(s.total_in<<3), (unsigned long)s.total_in,
               (unsigned long)(outtot+prod), last, type);
        outtot += prod;
        if (ret == Z_STREAM_END) { printf("stream end\n"); break; }
        if (ret != Z_OK) { printf("err %d\n", ret); break; }
        if (s.avail_in == 0 && feof(f)) { printf("EOF reached\n"); break; }
    }
    (void)intot;
    inflateEnd(&s);
    return 0;
}
EOF
cd /tmp/tools && gcc -O2 -o blockinfo blockinfo.c -lz && echo built"}

