{"command": "cat > /tmp/tools/blk.py <<'EOF'
import sys, struct
class BR:
    def __init__(self, d):
        self.d = d; self.p = 0; self.bit = 0
    def bits(self, n):
        v = 0
        for i in range(n):
            v |= ((self.d[self.p] >> self.bit) & 1) << i
            self.bit += 1
            if self.bit == 8:
                self.bit = 0; self.p += 1
        return v
    def align(self):
        if self.bit: self.bit = 0; self.p += 1
def parse(d):
    r = BR(d)
    blk = 0
    pos0 = r.p
    while True:
        last = r.bits(1)
        btype = r.bits(2)
        if btype == 0:
            r.align()
            ln = r.d[r.p] | (r.d[r.p+1] << 8); nl = r.d[r.p+2] | (r.d[r.p+3] << 8)
            print("blk %d last=%d STORED len=%d out_end=%d" % (blk, last, ln, r.p+4+ln))
            r.p += 4 + ln
        else:
            print("blk %d last=%d TYPE=%d out_end=%d" % (blk, last, btype, r.p))
            # cannot continue without full huffman decode; stop
            return
        blk += 1
        if last: break
    print("end at byte %d (of %d)" % (r.p, len(d)))
if __name__ == '__main__':
    d = open(sys.argv[1],'rb').read()
    parse(d)
EOF
cd /tmp/t && /workspace/executable -n -c -0 -R -b 1024 z1.bin > z1.0rs.gz && python3 /tmp/tools/blk.py z1.0rs.gz | head -25"}

