def test(name, vals, positions):
    # positions[i] = hash at position i (i = index of "end of window" - 1 maybe)
    d = collections.defaultdict(list)
    for i, h in zip(positions, vals):
        d[h].append(i)
    for target, lst in d.items():
        ls = set(lst)
        if ls == S:
            print("MATCH %s target=%r (end-index)" % (name, target))
        if set(x+1 for x in lst) == S:
            print("MATCH %s target=%r (start-index)" % (name, target))
    return d

res = []
def run(name, vals, idxs):
    d = collections.defaultdict(list)
    for i, h in zip(idxs, vals):
        d[h].append(i)
    for t, lst in d.items():
        if set(lst) == S: print("MATCH %s target=%d endpos" % (name, t))
        if set(x+1 for x in lst) == S: print("MATCH %s target=%d startpos" % (name, t))
    return len(d)

M32 = 1<<32
# additive multiplicative rolling: h = sum_j w[j]*C^j mod M ; window = data[i-W+1..i]
for C in (2,3,4,5,6,8,16,31,32,33,37,64,127,128,129,255,256,257,511,512,513,65599,1000003):
    for rev in (0,1):
        for M in (M32, 1<<24, 1<<16, 65521, 1<<31, 2**32-1):
            pw = [pow(C, j, M) for j in range(W)]
            # incremental
            h = 0
            for j in range(W):
                h = (h + data[j]*pw[j]) % M if rev==0 else (h + data[j]*pw[W-1-j]) % M
            vals = []
            idxs = []
            if W <= len(data):
                idxs.append(W-1); vals.append(h)
                for i in range(W, n):
                    if rev==0:
                        h = (h - data[i-W]*pw[0]) * 1
                        # shift: multiply all by C and add new byte * C^(W-1)
                        h = (h * C + data[i]*(pw[W-1]) - data[i-W]*1) % M
                    else:
                        h = (h - data[i-W]*pw[W-1]) 
                        h = (h * C + data[i]*1) % M
                    idxs.append(i); vals.append(h)
            k = run("mult C=%d rev=%d M=%x" % (C, rev, M), vals, idxs)
