def sim(w, k, width, op, xor_in=0xFF):
    mask = (1 << width) - 1
    s = 0
    for b in w:
        if op == 'xor':
            s = ((s << k) ^ b) & mask
        elif op == 'add':
            s = ((s << k) + b) & mask
        elif op == 'xorb8':
            s = ((s << k) ^ (b << 8)) & mask
        elif op == 'rotl':
            s = (((s << k) | (s >> (width - k))) ^ b) & mask
        elif op == 'rotr':
            s = (((s >> k) | (s << (width - k))) ^ b) & mask
