import sys
class BitR:
    def __init__(self, d, off=0):
        self.d=d; self.p=off; self.bit=0
    def bits(self,n):
        v=0
        for i in range(n):
            v |= ((self.d[self.p]>>self.bit)&1)<<i
            self.bit+=1
            if self.bit==8: self.bit=0; self.p+=1
        return v
    def align(self):
        if self.bit: self.bit=0; self.p+=1

def build(lengths):
    # canonical huffman decode table: returns dict (len,code)->sym
    maxlen=max(lengths) if lengths else 0
    bl_count=[0]*(maxlen+1)
    for l in lengths:
        if l: bl_count[l]+=1
    code=0; next_code=[0]*(maxlen+2)
    for bits in range(1,maxlen+1):
        code=(code+bl_count[bits-1])<<1
        next_code[bits]=code
    table={}
    for sym,l in enumerate(lengths):
        if l:
            table[(l,next_code[l])]=sym
            next_code[l]+=1
    return table,maxlen

def decode_sym(r, table, maxlen):
    code=0
    for l in range(1,maxlen+1):
        code=(code<<1)|r.bits(1)
        if (l,code) in table: return table[(l,code)]
    raise ValueError("bad code")

