/* try deflate call sequences to match pigz */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

int main(int argc, char **argv) {
    int level = atoi(argv[1]);
    int block = atoi(argv[2]);
    int indep = atoi(argv[3]);
    int strategy = atoi(argv[4]);
    int mode = atoi(argv[5]);
    const char *file = argv[6];
    FILE *f = fopen(file,"rb");
    size_t cap = 1<<28;
    unsigned char *in = malloc(cap);
    size_t n = fread(in, 1, cap, f);
    unsigned char *out = malloc(cap + (1<<20));
    size_t outn = 0, pos = 0;
    while (pos < n) {
        size_t len = (n - pos < (size_t)block) ? n - pos : block;
        z_stream s; memset(&s,0,sizeof(s));
        deflateInit2(&s, level, Z_DEFLATED, -15, 8, strategy);
        if (!indep && pos > 0) {
            size_t ds = pos > 32768 ? pos-32768 : 0;
            deflateSetDictionary(&s, in+ds, (uInt)(pos-ds));
        }
        s.next_in = in+pos; s.avail_in = (uInt)len;
        s.next_out = out+outn; s.avail_out = (uInt)(cap + (1<<20) - outn);
        int ret;
        switch (mode) {
        case 1: /* data with NO_FLUSH then SYNC_FLUSH */
            ret = deflate(&s, Z_NO_FLUSH);
            ret = deflate(&s, Z_SYNC_FLUSH);
            break;
        case 2: /* then sync flush twice */
            deflate(&s, Z_NO_FLUSH);
            deflate(&s, Z_SYNC_FLUSH);
            deflate(&s, Z_SYNC_FLUSH);
            break;
        case 3: /* single sync flush call */
            deflate(&s, Z_SYNC_FLUSH);
            break;
        case 4: /* full flush */
            deflate(&s, Z_NO_FLUSH);
            deflate(&s, Z_FULL_FLUSH);
            break;
        case 5: /* three sync flushes */
            deflate(&s, Z_NO_FLUSH);
            deflate(&s, Z_SYNC_FLUSH);
            deflate(&s, Z_SYNC_FLUSH);
            deflate(&s, Z_SYNC_FLUSH);
            break;
        case 6: /* finish */
            deflate(&s, Z_NO_FLUSH);
            deflate(&s, Z_FINISH);
            break;
        case 7: /* sync flush on data, then finish */
            deflate(&s, Z_SYNC_FLUSH);
            deflate(&s, Z_FINISH);
            break;
        }
        outn = cap + (1<<20) - s.avail_out;
        deflateEnd(&s);
        pos += len;
    }
    fwrite(out,1,outn,stdout);
    return 0;
}
EOF
