/* mode: 0 = NO_FLUSH then SYNC; 1 = PARTIAL then SYNC; 2 = PARTIAL then SYNC x loop */
int main(int argc,char**argv){
    int mode=atoi(argv[1]);
    int block=atoi(argv[2]);
    FILE*f=fopen(argv[3],"rb");
    size_t cap=1<<24; unsigned char*in=malloc(cap); size_t n=fread(in,1,cap,f);
    unsigned char*out=malloc(cap+65536); size_t outn=0;
    z_stream s; memset(&s,0,sizeof(s));
    deflateInit2(&s,6,Z_DEFLATED,-15,8,0);
    size_t pos=0;
    while(pos<n){
        size_t len=(n-pos<(size_t)block)?n-pos:block;
        s.next_in=in+pos; s.avail_in=(uInt)len;
        s.next_out=out+outn; s.avail_out=(uInt)(cap+65536-outn);
        int ret=deflate(&s,Z_NO_FLUSH);
        size_t before=cap+65536-s.avail_out;
        if(mode==0){ deflate(&s,Z_SYNC_FLUSH); }
        else {
            deflate(&s,Z_PARTIAL_FLUSH);
            int loops=0;
            while(loops<6){ 
                size_t b2=cap+65536-s.avail_out;
                deflate(&s,Z_SYNC_FLUSH);
                if (cap+65536-s.avail_out==b2) break;
                loops++;
            }
        }
        outn=cap+65536-s.avail_out;
        (void)before;(void)ret;
        pos+=len;
    }
    deflateEnd(&s);
    fwrite(out,1,outn,stdout);
    return 0;
}
