        if (usedict && pos>0){ size_t ds=pos>32768?pos-32768:0; deflateSetDictionary(&s,in+ds,(uInt)(pos-ds)); }
        s.next_in=in+pos; s.avail_in=(uInt)len;
        s.next_out=out+outn; s.avail_out=(uInt)(cap+65536-outn);
        deflate(&s,Z_NO_FLUSH);
        int last=(pos+len>=n);
        for (int i=0;i<nseq;i++){
            int fl=seq[i];
            if (last && i==nseq-1 && fl!=4) fl=4;
            deflate(&s,fl);
            if (!last || i<nseq-1){
                unsigned pend; int bits;
                deflatePending(&s,&pend,&bits);
                fprintf(stderr,"  after flush %d: pending=%u bits=%d total_out=%lu\n", fl, pend, bits, (unsigned long)s.total_out);
            }
        }
        if (last && nseq==0) deflate(&s,Z_FINISH);
        outn=cap+65536-s.avail_out;
        deflateEnd(&s);
        pos+=len;
    }
    fwrite(out,1,outn,stdout);
    return 0;
}
