/* Core compression model matching pigz */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

static int level=6, strategy=Z_DEFAULT_STRATEGY, indep=0, rsync=0;
static size_t block=131072;

/* compress data[0..n) into out (raw deflate), returns length */
static size_t compress_all(unsigned char *in, size_t n, unsigned char *out, size_t cap){
    size_t outn=0, pos=0;
    int blkn=0;
    while (pos < n) {
        size_t len;
        int last;
        if (rsync) {
            /* find the rsync boundary */
            size_t limit = pos + block;
            size_t end = n < limit ? n : limit;
            size_t i = pos;
            unsigned h = 0;   /* rolling hash state -- needs previous state; recompute for test */
            /* NOTE: state is continuous across blocks; for the test we track it */
            len = end - pos; last = 0;
            /* (rsync handled by caller in the real implementation) */
        } else {
            len = (n - pos < block) ? n - pos : block;
            last = (pos + len >= n);
        }
        z_stream s; memset(&s,0,sizeof(s));
        deflateInit2(&s, level, Z_DEFLATED, -15, 8, strategy);
        if (!indep && pos > 0) {
            size_t ds = pos > 32768 ? pos-32768 : 0;
            deflateSetDictionary(&s, in+ds, (uInt)(pos-ds));
        }
        s.next_in = in+pos; s.avail_in = (uInt)len;
        s.next_out = out+outn; s.avail_out = (uInt)(cap-outn);
        deflate(&s, Z_NO_FLUSH);
        int r;
        if (last) {
            r = deflate(&s, Z_FINISH);
        } else {
            unsigned pend; int bits;
            deflate(&s, Z_BLOCK);
            deflatePending(&s, &pend, &bits);
            int guard=0;
            while (bits && guard<20) {
                if (bits & 1) { deflate(&s, Z_SYNC_FLUSH); deflate(&s, Z_BLOCK); }
                else { deflate(&s, Z_PARTIAL_FLUSH); deflate(&s, Z_BLOCK); }
                deflatePending(&s, &pend, &bits);
                guard++;
            }
        }
        outn = cap - s.avail_out;
        deflateEnd(&s);
        pos += len; blkn++;
    }
    return outn;
}

int main(int argc, char **argv){
    /* args: level block indep rsync strategy file */
    level = atoi(argv[1]); block = atol(argv[2]); indep=atoi(argv[3]); rsync=atoi(argv[4]);
    strategy = atoi(argv[5]);
