{"command": "cd /tmp/tools && cat > core2.c <<'CEOF'
/* Core compression model: per-block fresh streams, optional dictionary, alignment */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
static int level=6, strategy=0, indep=0, dict=1, marker=0;
static size_t block=131072;
int main(int argc, char **argv){
    level=atoi(argv[1]); block=atol(argv[2]); indep=atoi(argv[3]); dict=atoi(argv[4]); strategy=atoi(argv[5]); marker=atoi(argv[6]);
    FILE *f=strcmp(argv[7],"-")?fopen(argv[7],"rb"):stdin;
    size_t cap=1<<28;
    unsigned char *in=malloc(cap); size_t n=fread(in,1,cap,f);
    unsigned char *out=malloc(cap+(1<<20)); size_t outn=0, pos=0;
    while (pos<n) {
        size_t len=(n-pos<block)?n-pos:block;
        int last=(pos+len>=n);
        z_stream s; memset(&s,0,sizeof(s));
        deflateInit2(&s,level,Z_DEFLATED,-15,8,strategy);
        if (dict && !indep && pos>0){ size_t ds=pos>32768?pos-32768:0; deflateSetDictionary(&s,in+ds,(uInt)(pos-ds)); }
        if (marker) {   /* prepend an empty stored block for independent blocks */
            unsigned char m[5]={0,0,0,0xff,0xff};
            memcpy(out+outn, m, 5); outn+=5;
        }
        s.next_in=in+pos; s.avail_in=(uInt)len;
        s.next_out=out+outn; s.avail_out=(uInt)(cap+(1<<20)-outn);
        deflate(&s,Z_NO_FLUSH);
        int r;
        if (last) r=deflate(&s,Z_FINISH);
        else {
            unsigned pend; int bits;
            deflate(&s,Z_BLOCK);
            deflatePending(&s,&pend,&bits);
            int g=0;
            while (bits && g<20){ if (bits&1){deflate(&s,Z_SYNC_FLUSH);deflate(&s,Z_BLOCK);} else {deflate(&s,Z_PARTIAL_FLUSH);deflate(&s,Z_BLOCK);} deflatePending(&s,&pend,&bits); g++; }
        }
        outn=cap+(1<<20)-s.avail_out;
        deflateEnd(&s);
        pos+=len;
    }
    fwrite(out,1,outn,stdout);
    return 0;
}
CEOF
gcc -O2 -o core2 core2.c -lz && cd /tmp/t && for f in big.txt eng.txt zeros.bin; do for bs in 128 32; do
 /workspace/executable -n -i -c -b $bs $f > /tmp/p.gz; d=$(python3 -c "print(len(open('/tmp/p.gz','rb').read())-18)")
 /tmp/tools/core2 6 $((bs*1024)) 1 0 0 1 $f > /tmp/c.def; szc=$(stat -c%s /tmp/c.def)
 ok=$(cmp -s <(tail -c +11 /tmp/p.gz|head -c $szc) /tmp/c.def && echo OK || echo DIFF)
 echo "$f -b$bs -i : pigz=$d core=$szc $ok"
done; done"}

