/* full non-i model: per-block fresh streams + dictionary + policy A alignment */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
int main(int argc,char**argv){
    int level=atoi(argv[1]); size_t block=atol(argv[2]); int strategy=atoi(argv[3]);
    FILE*f=fopen(argv[4],"rb");
    size_t cap=1<<28; unsigned char*in=malloc(cap); size_t n=fread(in,1,cap,f);
    unsigned char*out=malloc(cap+(1<<20)); size_t outn=0, pos=0;
    while(pos<n){
        size_t len=(n-pos<(size_t)block)?n-pos:block;
        int last=(pos+len>=n);
        z_stream s; memset(&s,0,sizeof(s));
        deflateInit2(&s,level,Z_DEFLATED,-15,8,strategy);
        if (pos>0){ size_t ds=pos>32768?pos-32768:0; deflateSetDictionary(&s,in+ds,(uInt)(pos-ds)); }
        s.next_in=in+pos; s.avail_in=(uInt)len;
        s.next_out=out+outn; s.avail_out=(uInt)(cap+(1<<20)-outn);
        int r;
        if (last) {
            r=deflate(&s,Z_FINISH);
