                else { deflate(&s,Z_PARTIAL_FLUSH); deflate(&s,Z_BLOCK); }
                deflatePending(&s,&pend,&bits);
                g++;
            }
        }
        outn=cap+(1<<20)-s.avail_out;
        deflateEnd(&s);
        pos+=len;
    }
    fwrite(out,1,outn,stdout);
    return 0;
}
