            else if (strcmp(p, "--force") == 0) g.force++;
            else if (strcmp(p, "--help") == 0) g.mode = OP_HELP;
            else if (strcmp(p, "--huffman") == 0) g.strategy = 2;
            else if (strcmp(p, "--rle") == 0) g.strategy = 3;
            else if (strcmp(p, "--independent") == 0) g.indep = 1;
            else if (strcmp(p, "--keep") == 0) g.keep++;
            else if (strcmp(p, "--list") == 0) g.mode = OP_LIST;
            else if (strcmp(p, "--license") == 0) g.mode = OP_LICENSE;
            else if (strcmp(p, "--no-time") == 0) g.head_time = 0;
            else if (strcmp(p, "--time") == 0) g.head_time = 1;
            else if (strcmp(p, "--no-name") == 0) { g.head = 0; g.head_time = 0; }
            else if (strcmp(p, "--name") == 0) { g.head = 1; g.head_time = 1; }
            else if (strcmp(p, "--quiet") == 0) g.verbosity = 0;
            else if (strcmp(p, "--silent") == 0) g.verbosity = 0;
            else if (strcmp(p, "--recursive") == 0) g.recurse++;
            else if (strcmp(p, "--rsyncable") == 0) g.rsync = 1;
            else if (strcmp(p, "--suffix") == 0) g.sufx = get_string("--suffix");
            else if (strcmp(p, "--test") == 0) g.mode = OP_TEST;
            else if (strcmp(p, "--verbose") == 0) g.verbosity++;
            else if (strcmp(p, "--version") == 0) g.mode = OP_VERSION;
            else if (strcmp(p, "--blocksize") == 0) {
                unsigned long n = get_optnum("--blocksize");
                if (n < 32) abort_msg("block size too small (must be >= 32K)");
                if (n > 524288) abort_msg("block size too large: %lu", n);
                g.block = (size_t)n << 10;
            }
            else if (strcmp(p, "--processes") == 0) {
                unsigned long n = get_optnum("--processes");
                if (n > 2147483647UL || n == 0)
                    abort_msg("invalid number of processes: %lu", n);
                g.procs = (int)n;
            }
            else if (strcmp(p, "--alias") == 0) g.alias = get_string("--alias");
            else if (strcmp(p, "--comment") == 0) g.comment = get_string("--comment");
            else if (strcmp(p, "--first") == 0) g.first = 1;
            else if (strcmp(p, "--iterations") == 0) g.iterations = (int)get_optnum("--iterations");
            else if (strcmp(p, "--maxsplits") == 0) g.maxsplits = (int)get_optnum("--maxsplits");
            else if (strcmp(p, "--oneblock") == 0) g.oneblock = 1;
            else if (strcmp(p, "--synchronous") == 0) g.sync = 1;
            else if (strcmp(p, "--zlib") == 0) g.form = 1;
            else if (strcmp(p, "--zip") == 0) g.form = 2;
            else if (strcmp(p, "--stdout") == 0) g.to_stdout = 1;
            else abort_msg("invalid option: %s", oargv[optidx]);
            return 1;
        default:
            { char buf[3]; buf[0]='-'; buf[1]=*p; buf[2]=0;
              abort_msg("invalid option: %s", buf); }
        }
        p++;
    }
    return 1;
}

static void parse_env(char *val)
{
    /* split on whitespace, treat each token as an option */
    char *copy = strdup(val);
    char **tmp = malloc(sizeof(char *) * 64);
    int n = 0;
    char *p = strtok(copy, " \t");
    while (p && n < 63) { tmp[n++] = p; p = strtok(NULL, " \t"); }
    for (int i = 0; i < n; i++) {
        if (tmp[i][0] == '-') { optidx = 0; oargv = tmp; oargc = n; short_opt(tmp[i]+1); }
    }
    free(tmp); free(copy);
}

static void parse_args(int argc, char **argv)
{
    int i;
    for (i = 1; i < argc; i++) {
        if (no_more_opts) break;
        if (argv[i][0] == '-' && argv[i][1] != 0) {
            oargv = argv; oargc = argc;
            if (strcmp(argv[i], "--") == 0) { no_more_opts = 1; continue; }
            if (short_opt(argv[i] + 1) == 0) { no_more_opts = 1; continue; }
            /* if an option consumed a parameter, skip it */
            continue;
        } else break;
    }
    optidx = i;
}

/* ---------------- listing ---------------- */
static void list_date(char *buf, size_t n, long long mtime, int have_time)
{
    time_t t = (time_t)mtime;
    struct tm *lt, now;
    time_t curt = time(NULL);
    if (!have_time) { strcpy(buf, "------ -----"); return; }
    lt = localtime(&t);
    localtime_r(&curt, &now);
    if (lt && now.tm_year == lt->tm_year)
        strftime(buf, n, "%b %e %H:%M", lt);
    else
        strftime(buf, n, "%b %e  %Y", lt);
}

static void list_file(char *name, char *showname, long long mtime, int have_time,
                      int method, unsigned long check, int have_check,
                      long long comp, int have_comp,
                      long long orig, int have_orig)
{
    char datebuf[64];
    double ratio = 0.0;
    if (g.verbosity > 1) {
        const char *meth = g.form == 2 ? "zip" : (g.form == 1 ? "zlib" : "gzip");
        char chk[16];
        if (have_check) snprintf(chk, sizeof chk, "%08lx", check);
        else strcpy(chk, "--------");
        list_date(datebuf, sizeof datebuf, mtime, have_time);
        printf("%-4s %d  %s  %s ", meth, method, chk, datebuf);
    }
    if (have_comp && have_orig) {
        if (orig == 0) ratio = (orig - (double)comp) / 1.0;
        ratio = (orig - (double)comp) * 100.0 / (double)orig;
        printf("%10lld %10lld %6.1f%%  %s\n", comp, orig, ratio, showname);
    } else {
        printf("%10lld %11s %4s    %s\n", comp, have_comp ? "" : "0?",
               "unk", showname);
    }
}

/* ---------------- compression ---------------- */
/* rsyncable rolling hash state, kept across blocks */
static unsigned rsync_hash_state;

static int rsync_match(unsigned char *buf, size_t start, size_t len,
                       size_t *endpos, unsigned *state)
{
    size_t i;
    unsigned h = *state;
    for (i = start; i < len; i++) {
        h = ((h << 1) ^ buf[i]) & 0xffff;
        if ((h & 0xfff) == 0x7ff) { *endpos = i + 1; *state = h; return 1; }
    }
    *state = h;
    return 0;
}

/* compress the data in inbuf[0..len) as one pigz block */
static size_t deflate_block(z_stream *s, unsigned char *in, size_t len,
                            int last, unsigned char *out, size_t cap)
{
    int r;
    s->next_in = in; s->avail_in = (uInt)len;
    s->next_out = out; s->avail_out = (uInt)cap;
    if (last) {
        r = deflate(s, Z_FINISH);
        if (r != Z_STREAM_END) { msg("deflate error %d", r); exit(1); }
    } else {
        unsigned pend; int bits;
        deflate(s, Z_NO_FLUSH);
        r = deflate(s, Z_BLOCK);
        if (r != Z_OK && r != Z_BUF_ERROR) { msg("deflate error %d", r); exit(1); }
        deflatePending(s, &pend, &bits);
        int guard = 0;
        while (bits && guard < 20) {
            if (bits & 1) { deflate(s, Z_SYNC_FLUSH); deflate(s, Z_BLOCK); }
            else { deflate(s, Z_PARTIAL_FLUSH); deflate(s, Z_BLOCK); }
            deflatePending(s, &pend, &bits);
            guard++;
        }
    }
    return cap - s->avail_out;
}

/* write a stored-empty-block marker used by -i */
static void put_marker(FILE *out)
{
    static const unsigned char m[5] = {0,0,0,0xff,0xff};
    fwrite(m, 1, 5, out);
}

static void compress_stream(FILE *in, FILE *out, int is_stdin, char *name,
                            long long mtime, int have_time)
{
    size_t cap = g.block + 65536 + 1024;
    unsigned char *inbuf = malloc(g.block + 1);
    unsigned char *outbuf = malloc(cap);
    size_t pos = 0, inlen = 0;
    unsigned char *dict = malloc(32768);
    size_t dictlen = 0;
    int have_dict = 0;
    z_stream s;
    int first = 1;

    (void)is_stdin;
    /* write the header */
    if (g.form == 0) {
        unsigned char hdr[10];
        int flg = 0;
        if (g.head && name) flg |= 8;
        hdr[0] = 0x1f; hdr[1] = 0x8b; hdr[2] = 8;
        hdr[3] = (unsigned char)flg;
        if (g.head_time && have_time) {
            hdr[4] = (unsigned)(mtime & 0xff);
            hdr[5] = (unsigned)((mtime >> 8) & 0xff);
            hdr[6] = (unsigned)((mtime >> 16) & 0xff);
            hdr[7] = (unsigned)((mtime >> 24) & 0xff);
        } else { hdr[4] = hdr[5] = hdr[6] = hdr[7] = 0; }
        hdr[8] = (g.level == 1 || g.level == 11) ? 4 : (g.level == 9 ? 2 : 0);
        hdr[9] = 3;
        fwrite(hdr, 1, 10, out);
        if (flg & 8) fwrite(name, 1, strlen(name) + 1, out);
    } else if (g.form == 1) {
        unsigned char hdr[2] = {0x78, 0};
        int lvl = g.level == 11 ? 9 : g.level;
        hdr[1] = (unsigned char)(lvl >= 9 ? 0xda : (lvl >= 6 ? 0x9c :
                       (lvl == 1 ? 0x01 : (lvl == 0 ? 0x01 : 0x5e))));
        /* compute FCHK so that (hdr[0]<<8|hdr[1]) % 31 == 0 */
        {
            int f = ((0x78 << 8) | hdr[1]) % 31;
            if (f) hdr[1] = (unsigned char)(hdr[1] + 31 - f);
            if (hdr[1] & 0x20) hdr[1] = (unsigned char)(hdr[1] - 31);
        }
        fwrite(hdr, 1, 2, out);
    } else if (g.form == 2) {
        /* zip local file header -- filled in later with sizes */
        unsigned char hdr[30];
        time_t t = have_time && g.head_time ? (time_t)mtime : time(NULL);
        struct tm *lt = localtime(&t);
        unsigned dosdate, dostime;
        if (lt) {
            dostime = (unsigned)((lt->tm_hour << 11) | (lt->tm_min << 5) | (lt->tm_sec >> 1));
            dosdate = (unsigned)(((lt->tm_year - 80) << 9) | ((lt->tm_mon + 1) << 5) | lt->tm_mday);
        } else { dostime = 0; dosdate = 0x21; }
        memset(hdr, 0, sizeof hdr);
        hdr[0]='P'; hdr[1]='K'; hdr[2]=3; hdr[3]=4;
        hdr[4]=45; hdr[5]=0;
        hdr[6]=8;              /* flags: deflate */
        hdr[7]=0;
        hdr[8]=(unsigned char)(dostime & 0xff); hdr[9]=(unsigned char)(dostime>>8);
        hdr[10]=(unsigned char)(dosdate & 0xff); hdr[11]=(unsigned char)(dosdate>>8);
        /* crc and sizes are zero, patched after */
        hdr[26]=0x14; hdr[27]=0;   /* extra field length 20 */
        if (g.alias) {
            size_t nl = strlen(g.alias);
            hdr[26] = (unsigned char)(20 + ((nl > 65535) ? 65535 : nl));
            hdr[27] = (unsigned char)((20 + nl) >> 8);
        } else if (g.head && name) {
            size_t nl = strlen(name);
            if (nl > 255) nl = 255;
            hdr[26] = (unsigned char)(20 + nl);
            hdr[27] = (unsigned char)((20 + nl) >> 8);
        }
        hdr[28] = 20; hdr[29] = 0;  /* extra field length low */
        fwrite(hdr, 1, sizeof hdr, out);
        /* extra field: UT (0x5554) */
        {
            unsigned char ex[28];
            memset(ex, 0, sizeof ex);
            ex[0]='U'; ex[1]='T'; ex[2]=5; ex[3]=0; ex[4]=1;
            if (g.head_time && have_time) {
                ex[5] = (unsigned)(mtime & 0xff); ex[6] = (unsigned)((mtime>>8)&0xff);
                ex[7] = (unsigned)((mtime>>16)&0xff); ex[8] = (unsigned)((mtime>>24)&0xff);
            }
            ex[9]='U'; ex[10]='x'; ex[11]=0; ex[12]=0;
            fwrite(ex, 1, 20, out);
            if (g.alias) fwrite(g.alias, 1, strlen(g.alias), out);
            else if (g.head && name) fwrite(name, 1, strlen(name), out);
        }
    }

    /* compress */
    unsigned long crc = crc32(0L, Z_NULL, 0);
    unsigned long adler = adler32(0L, Z_NULL, 0);
    unsigned long long total = 0;

    while (1) {
        size_t len;
        int last = 0;
        /* read a block */
        len = fread(inbuf, 1, g.block, in);
        if (len == 0) {
            if (ferror(in)) { skip_msg("read error on input"); exit(1); }
            last = 1;
        }
        /* rsyncable: adjust the block boundary */
        if (g.rsync && !last && len > 0) {
            size_t endpos;
            if (rsync_match(inbuf, 0, len, &endpos, &rsync_hash_state))
                len = endpos;
        }
        if (len == 0) {
            /* end of input */
            break;
        }
        /* start a new deflate stream for this block */
        memset(&s, 0, sizeof(s));
        deflateInit2(&s, g.level == 11 ? 9 : g.level, Z_DEFLATED, -15, 8, g.strategy);
        if (!g.indep && have_dict)
            deflateSetDictionary(&s, dict, (uInt)dictlen);
        if (g.indep && !first) put_marker(out);
        /* compress this block */
        {
            int lastblk = 0;
            unsigned char *inp = inbuf;
            size_t rem = len;
            size_t produced = 0;
            /* handle rsync: the block may be shorter than len */
            unsigned char *blkbuf = inbuf;
            size_t blklen = len;
            produced = deflate_block(&s, blkbuf, blklen, 0, outbuf, cap);
            fwrite(outbuf, 1, produced, out);
            crc = crc32(crc, blkbuf, (uInt)blklen);
            adler = adler32(adler, blkbuf, (uInt)blklen);
            total += blklen;
            /* save the dictionary for the next block */
            if (blklen >= 32768) memcpy(dict, blkbuf + blklen - 32768, 32768);
            else if (dictlen + blklen <= 32768) {
                memmove(dict, dict + blklen, dictlen);
                memcpy(dict + (dictlen > blklen ? dictlen - blklen : 0), blkbuf, blklen);
                dictlen = dictlen + blklen > 32768 ? 32768 : dictlen + blklen;
            } else {
                size_t need = 32768 - blklen;
                memmove(dict, dict + (dictlen - need), need);
                memcpy(dict + need, blkbuf, blklen);
                dictlen = 32768;
            }
            have_dict = 1;
            first = 0;
            pos += blklen;
        }
        deflateEnd(&s);
        if (last) break;
    }
    /* the last block: deflate with Z_FINISH (pigz emits the final block) */
    if (!last_done_marker) ;
    free(inbuf); free(outbuf); free(dict);
}
