/* pigz.c -- reimplementation of pigz 2.8 (parallel gzip) */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <utime.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <zlib.h>

#define PIGZ_VERSION "2.8"

typedef enum { OP_COMPILE, OP_DECOMPRESS, OP_LIST, OP_TEST,
               OP_LICENSE, OP_HELP, OP_VERSION } op_t;

static struct {
    op_t mode;
    int head;          /* store name in header */
    int head_time;     /* store mtime in header */
    int level;
    int strategy;
    int indep;
    int rsync;
    int sync;          /* -Y */
    int verbosity;
    int form;          /* 0=gzip 1=zlib 2=zip */
    size_t block;
    int procs;
    int force;
    int keep;
    int recurse;
    int to_stdout;
    char *comment;
    char *alias;
    char *sufx;
    int first, iterations, maxsplits, oneblock;
} g;

static char *prog;
static int errcnt;
static int no_more_opts;

/* ---------------- messages ---------------- */
static void msg(const char *fmt, ...)
{
    va_list ap;
    if (g.verbosity == 0) return;
    fprintf(stderr, "%s: ", prog);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
}
/* skipping: warns and counts as error */
static void skip_msg(const char *fmt, ...)
{
    va_list ap;
    if (g.verbosity == 0) { errcnt++; return; }
    fprintf(stderr, "%s: skipping: ", prog);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
    errcnt++;
}
static void abort_msg(const char *fmt, ...)
{
    va_list ap;
    if (g.verbosity != 0) {
        fprintf(stderr, "%s: abort: ", prog);
        va_start(ap, fmt);
        vfprintf(stderr, fmt, ap);
        va_end(ap);
        fputc('\n', stderr);
    }
    exit(22);
}

/* ---------------- help text ---------------- */
static const char *usage_text =
"Usage: pigz [options] [files ...]\n"
"  will compress files in place, adding the suffix '.gz'. If no files are\n"
"  specified, stdin will be compressed to stdout. pigz does what gzip does,\n"
"  but spreads the work over multiple processors and cores when compressing.\n"
"\n"
"Options:\n"
"  -0 to -9, -11        Compression level (level 11, zopfli, is much slower)\n"
"  --fast, --best       Compression levels 1 and 9 respectively\n"
"  -A, --alias xxx      Use xxx as the name for any --zip entry from stdin\n"
"  -b, --blocksize mmm  Set compression block size to mmmK (default 128K)\n"
"  -c, --stdout         Write all processed output to stdout (won't delete)\n"
"  -C, --comment ccc    Put comment ccc in the gzip or zip header\n"
"  -d, --decompress     Decompress the compressed input\n"
"  -f, --force          Force overwrite, compress .gz, links, and to terminal\n"
"  -F  --first          Do iterations first, before block split for -11\n"
"  -h, --help           Display a help screen and quit\n"
"  -H, --huffman        Use only Huffman coding for compression\n"
"  -i, --independent    Compress blocks independently for damage recovery\n"
"  -I, --iterations n   Number of iterations for -11 optimization\n"
"  -J, --maxsplits n    Maximum number of split blocks for -11\n"
"  -k, --keep           Do not delete original file after processing\n"
"  -K, --zip            Compress to PKWare zip (.zip) single entry format\n"
"  -l, --list           List the contents of the compressed input\n"
"  -L, --license        Display the pigz license and quit\n"
"  -m, --no-time        Do not store or restore mod time\n"
"  -M, --time           Store or restore mod time\n"
"  -n, --no-name        Do not store or restore file name or mod time\n"
"  -N, --name           Store or restore file name and mod time\n"
"  -O  --oneblock       Do not split into smaller blocks for -11\n"
"  -p, --processes n    Allow up to n compression threads (default is the\n"
"                       number of online processors, or 8 if unknown)\n"
"  -q, --quiet          Print no messages, even on error\n"
"  -r, --recursive      Process the contents of all subdirectories\n"
"  -R, --rsyncable      Input-determined block locations for rsync\n"
"  -S, --suffix .sss    Use suffix .sss instead of .gz (for compression)\n"
"  -t, --test           Test the integrity of the compressed input\n"
"  -U, --rle            Use run-length encoding for compression\n"
"  -v, --verbose        Provide more verbose output\n"
"  -V  --version        Show the version of pigz\n"
"  -Y  --synchronous    Force output file write to permanent storage\n"
"  -z, --zlib           Compress to zlib (.zz) instead of gzip format\n"
"  --                   All arguments after \"--\" are treated as files\n";

/* ---------------- option parsing ---------------- */
static int optidx;      /* current index in argv */
static char **oargv;
static int oargc;

static void get_parameter(char *what)
{
    if (optidx + 1 >= oargc || (oargv[optidx+1][0] == '-' && oargv[optidx+1][1] != 0))
        abort_msg("missing parameter after %s", what);
    optidx++;
}
/* parse a positive decimal number; abort if invalid */
static unsigned long get_number(char *what)
{
    char *endp; unsigned long val;
    get_parameter(what);
    errno = 0;
    val = strtoul(oargv[optidx], &endp, 10);
    if (oargv[optidx][0] == 0 || *endp != 0 || errno)
        abort_msg("invalid numeric parameter: %s", oargv[optidx]);
    return val;
}
static unsigned long get_optnum(char *what)
{
    char *endp; unsigned long val;
    get_parameter(what);
    errno = 0;
    val = strtoul(oargv[optidx], &endp, 10);
    if (oargv[optidx][0] == 0 || *endp != 0 || errno)
        abort_msg("invalid numeric parameter: %s", oargv[optidx]);
    return val;
}
static char *get_string(char *what)
{
    get_parameter(what);
    return oargv[optidx];
}

static int short_opt(char *arg)
{
    /* process a group of short options starting at arg[0] */
    char *p = arg;
    while (*p) {
        switch (*p) {
        case '0': case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8': case '9':
            if (*p == '1' && p[1] == '1' && p[2] == 0) {
                g.level = 11; return 1;
            }
            if (*p == '0') g.level = 0;
            else g.level = *p - '0';
            break;
        case 'A': g.alias = get_string("-A"); break;
        case 'b': {
            unsigned long n = get_optnum("-b");
            if (n < 32) abort_msg("block size too small (must be >= 32K)");
            if (n > 524288) abort_msg("block size too large: %lu", n);
            g.block = (size_t)n << 10;
            break;
        }
        case 'C': g.comment = get_string("-C"); break;
        case 'd': g.mode = OP_DECOMPRESS; break;
        case 'f': g.force++; break;
        case 'F': g.first = 1; break;
        case 'h': g.mode = OP_HELP; break;
        case 'H': g.strategy = 2; break;
        case 'i': g.indep = 1; break;
        case 'I': g.iterations = (int)get_optnum("-I"); break;
        case 'J': g.maxsplits = (int)get_optnum("-J"); break;
        case 'k': g.keep++; break;
        case 'K': g.form = 2; break;
        case 'l': g.mode = OP_LIST; break;
        case 'L': g.mode = OP_LICENSE; break;
        case 'm': g.head_time = 0; break;
        case 'M': g.head_time = 1; break;
        case 'n': g.head = 0; g.head_time = 0; break;
        case 'N': g.head = 1; g.head_time = 1; break;
        case 'O': g.oneblock = 1; break;
        case 'p': {
            unsigned long n = get_optnum("-p");
            if (n > 2147483647UL || n == 0)
                abort_msg("invalid number of processes: %lu", n);
            g.procs = (int)n;
            break;
        }
        case 'q': g.verbosity = 0; break;
        case 'r': g.recurse++; break;
        case 'R': g.rsync = 1; break;
        case 'S': g.sufx = get_string("-S"); break;
        case 't': g.mode = OP_TEST; break;
        case 'U': g.strategy = 3; break;
        case 'v': g.verbosity++; break;
        case 'V': g.mode = OP_VERSION; break;
        case 'Y': g.sync = 1; break;
        case 'z': g.form = 1; break;
        case '-':
            if (p[1] == 0) { no_more_opts = 1; return 0; }
            if (strcmp(p, "--") == 0) { no_more_opts = 1; return 0; }
            if (strcmp(p, "--fast") == 0) g.level = 1;
            else if (strcmp(p, "--best") == 0) g.level = 9;
            else if (strcmp(p, "--stdout") == 0) g.to_stdout = 1;
            else if (strcmp(p, "--to-stdout") == 0) g.to_stdout = 1;
            else if (strcmp(p, "--decompress") == 0) g.mode = OP_DECOMPRESS;
            else if (strcmp(p, "--uncompress") == 0) g.mode = OP_DECOMPRESS;
            else if (strcmp(p, "--force") == 0) g.force++;
            else if (strcmp(p, "--help") == 0) g.mode = OP_HELP;
            else if (strcmp(p, "--huffman") == 0) g.strategy = 2;
            else if (strcmp(p, "--rle") == 0) g.strategy = 3;
            else if (strcmp(p, "--independent") == 0) g.indep = 1;
            else if (strcmp(p, "--keep") == 0) g.keep++;
            else if (strcmp(p, "--list") == 0) g.mode = OP_LIST;
            else if (strcmp(p, "--license") == 0) g.mode = OP_LICENSE;
            else if (strcmp(p, "--no-time") == 0) g.head_time = 0;
            else if (strcmp(p, "--time") == 0) g.head_time = 1;
            else if (strcmp(p, "--no-name") == 0) { g.head = 0; g.head_time = 0; }
            else if (strcmp(p, "--name") == 0) { g.head = 1; g.head_time = 1; }
            else if (strcmp(p, "--quiet") == 0) g.verbosity = 0;
            else if (strcmp(p, "--silent") == 0) g.verbosity = 0;
            else if (strcmp(p, "--recursive") == 0) g.recurse++;
            else if (strcmp(p, "--rsyncable") == 0) g.rsync = 1;
            else if (strcmp(p, "--suffix") == 0) g.sufx = get_string("--suffix");
            else if (strcmp(p, "--test") == 0) g.mode = OP_TEST;
            else if (strcmp(p, "--verbose") == 0) g.verbosity++;
            else if (strcmp(p, "--version") == 0) g.mode = OP_VERSION;
            else if (strcmp(p, "--blocksize") == 0) {
                unsigned long n = get_optnum("--blocksize");
                if (n < 32) abort_msg("block size too small (must be >= 32K)");
                if (n > 524288) abort_msg("block size too large: %lu", n);
                g.block = (size_t)n << 10;
            }
            else if (strcmp(p, "--processes") == 0) {
                unsigned long n = get_optnum("--processes");
                if (n > 2147483647UL || n == 0)
                    abort_msg("invalid number of processes: %lu", n);
                g.procs = (int)n;
            }
            else if (strcmp(p, "--alias") == 0) g.alias = get_string("--alias");
            else if (strcmp(p, "--comment") == 0) g.comment = get_string("--comment");
            else if (strcmp(p, "--first") == 0) g.first = 1;
            else if (strcmp(p, "--iterations") == 0) g.iterations = (int)get_optnum("--iterations");
            else if (strcmp(p, "--maxsplits") == 0) g.maxsplits = (int)get_optnum("--maxsplits");
            else if (strcmp(p, "--oneblock") == 0) g.oneblock = 1;
            else if (strcmp(p, "--synchronous") == 0) g.sync = 1;
            else if (strcmp(p, "--zlib") == 0) g.form = 1;
            else if (strcmp(p, "--zip") == 0) g.form = 2;
            else if (strcmp(p, "--stdout") == 0) g.to_stdout = 1;
            else abort_msg("invalid option: %s", oargv[optidx]);
            return 1;
        default:
            { char buf[3]; buf[0]='-'; buf[1]=*p; buf[2]=0;
              abort_msg("invalid option: %s", buf); }
        }
        p++;
    }
    return 1;
}

static void parse_env(char *val)
{
    /* split on whitespace, treat each token as an option */
    char *copy = strdup(val);
    char **tmp = malloc(sizeof(char *) * 64);
    int n = 0;
    char *p = strtok(copy, " \t");
    while (p && n < 63) { tmp[n++] = p; p = strtok(NULL, " \t"); }
    for (int i = 0; i < n; i++) {
        if (tmp[i][0] == '-') { optidx = 0; oargv = tmp; oargc = n; short_opt(tmp[i]+1); }
    }
    free(tmp); free(copy);
}

static void parse_args(int argc, char **argv)
{
    int i;
    for (i = 1; i < argc; i++) {
        if (no_more_opts) break;
        if (argv[i][0] == '-' && argv[i][1] != 0) {
            oargv = argv; oargc = argc;
            if (strcmp(argv[i], "--") == 0) { no_more_opts = 1; continue; }
            if (short_opt(argv[i] + 1) == 0) { no_more_opts = 1; continue; }
            /* if an option consumed a parameter, skip it */
            continue;
        } else break;
    }
    optidx = i;
}

/* ---------------- listing ---------------- */
static void list_date(char *buf, size_t n, long long mtime, int have_time)
{
    time_t t = (time_t)mtime;
    struct tm *lt, now;
    time_t curt = time(NULL);
    if (!have_time) { strcpy(buf, "------ -----"); return; }
    lt = localtime(&t);
    localtime_r(&curt, &now);
    if (lt && now.tm_year == lt->tm_year)
        strftime(buf, n, "%b %e %H:%M", lt);
    else
        strftime(buf, n, "%b %e  %Y", lt);
}

static void list_file(char *name, char *showname, long long mtime, int have_time,
                      int method, unsigned long check, int have_check,
                      long long comp, int have_comp,
                      long long orig, int have_orig)
{
    char datebuf[64];
    double ratio = 0.0;
    if (g.verbosity > 1) {
        const char *meth = g.form == 2 ? "zip" : (g.form == 1 ? "zlib" : "gzip");
        char chk[16];
        if (have_check) snprintf(chk, sizeof chk, "%08lx", check);
        else strcpy(chk, "--------");
        list_date(datebuf, sizeof datebuf, mtime, have_time);
        printf("%-4s %d  %s  %s ", meth, method, chk, datebuf);
    }
    if (have_comp && have_orig) {
        if (orig == 0) ratio = (orig - (double)comp) / 1.0;
        ratio = (orig - (double)comp) * 100.0 / (double)orig;
        printf("%10lld %10lld %6.1f%%  %s\n", comp, orig, ratio, showname);
    } else {
        printf("%10lld %11s %4s    %s\n", comp, have_comp ? "" : "0?",
               "unk", showname);
    }
}

/* ---------------- compression ---------------- */
/* rsyncable rolling hash state, kept across blocks */
static unsigned rsync_hash_state;

static int rsync_match(unsigned char *buf, size_t start, size_t len,
                       size_t *endpos, unsigned *state)
{
    size_t i;
    unsigned h = *state;
    for (i = start; i < len; i++) {
        h = ((h << 1) ^ buf[i]) & 0xffff;
        if ((h & 0xfff) == 0x7ff) { *endpos = i + 1; *state = h; return 1; }
    }
    *state = h;
    return 0;
}

/* compress the data in inbuf[0..len) as one pigz block */
static size_t deflate_block(z_stream *s, unsigned char *in, size_t len,
                            int last, unsigned char *out, size_t cap)
{
    int r;
    s->next_in = in; s->avail_in = (uInt)len;
    s->next_out = out; s->avail_out = (uInt)cap;
    if (last) {
        r = deflate(s, Z_FINISH);
        if (r != Z_STREAM_END) { msg("deflate error %d", r); exit(1); }
    } else {
        unsigned pend; int bits;
        deflate(s, Z_NO_FLUSH);
        r = deflate(s, Z_BLOCK);
        if (r != Z_OK && r != Z_BUF_ERROR) { msg("deflate error %d", r); exit(1); }
        deflatePending(s, &pend, &bits);
        int guard = 0;
        while (bits && guard < 20) {
            if (bits & 1) { deflate(s, Z_SYNC_FLUSH); deflate(s, Z_BLOCK); }
            else { deflate(s, Z_PARTIAL_FLUSH); deflate(s, Z_BLOCK); }
            deflatePending(s, &pend, &bits);
            guard++;
        }
    }
    return cap - s->avail_out;
}

/* write a stored-empty-block marker used by -i */
static void put_marker(FILE *out)
{
    static const unsigned char m[5] = {0,0,0,0xff,0xff};
    fwrite(m, 1, 5, out);
}

