            hdr[4] = (unsigned)(mtime & 0xff);
            hdr[5] = (unsigned)((mtime >> 8) & 0xff);
            hdr[6] = (unsigned)((mtime >> 16) & 0xff);
            hdr[7] = (unsigned)((mtime >> 24) & 0xff);
        } else { hdr[4] = hdr[5] = hdr[6] = hdr[7] = 0; }
