            if (g.head_time && have_time) {
                ex[5] = (unsigned)(mtime & 0xff); ex[6] = (unsigned)((mtime>>8)&0xff);
                ex[7] = (unsigned)((mtime>>16)&0xff); ex[8] = (unsigned)((mtime>>24)&0xff);
            }
            ex[9]='U'; ex[10]='x'; ex[11]=0; ex[12]=0;
            fwrite(ex, 1, 20, out);
            if (g.alias) fwrite(g.alias, 1, strlen(g.alias), out);
            else if (g.head && name) fwrite(name, 1, strlen(name), out);
