        int lvl = g.level == 11 ? 9 : g.level;
        hdr[1] = (unsigned char)(lvl >= 9 ? 0xda : (lvl >= 6 ? 0x9c :
                       (lvl == 1 ? 0x01 : (lvl == 0 ? 0x01 : 0x5e))));
