            if (n == 0 || n > 2147483647UL) abort_msg("invalid number of processes: %lu", n);
            g.procs = (int)n; break; }
        case 'q': g.verbosity = 0; break;
        case 'r': g.recurse++; break;
        case 'R': g.rsync = 1; break;
        case 'S': g.sufx = get_string("-S"); break;
        case 't': g.mode = OP_TEST; break;
        case 'U': g.strategy = 3; break;
        case 'v': g.verbosity++; break;
        case 'V': g.mode = OP_VERSION; break;
        case 'Y': g.sync = 1; break;
        case 'z': g.form = 1; break;
        default: { char b[3]; b[0]='-'; b[1]=*p; b[2]=0;
                   abort_msg("invalid option: %s", b); }
        }
        p++;
    }
    return 1;
}
static int long_opt(char *p)
{
    if (!strcmp(p, "--")) { no_more_opts = 1; return 0; }
    else if (!strcmp(p, "--fast")) g.level = 1;
    else if (!strcmp(p, "--best")) g.level = 9;
    else if (!strcmp(p, "--stdout") || !strcmp(p,"--to-stdout")) g.to_stdout = 1;
    else if (!strcmp(p, "--decompress") || !strcmp(p,"--uncompress")) g.mode = OP_DECOMPRESS;
    else if (!strcmp(p, "--force")) g.force++;
    else if (!strcmp(p, "--help")) g.mode = OP_HELP;
    else if (!strcmp(p, "--huffman")) g.strategy = 2;
    else if (!strcmp(p, "--rle")) g.strategy = 3;
    else if (!strcmp(p, "--independent")) g.indep = 1;
    else if (!strcmp(p, "--keep")) g.keep++;
    else if (!strcmp(p, "--list")) g.mode = OP_LIST;
    else if (!strcmp(p, "--license")) g.mode = OP_LICENSE;
    else if (!strcmp(p, "--no-time")) g.head_time = 0;
    else if (!strcmp(p, "--time")) g.head_time = 1;
    else if (!strcmp(p, "--no-name")) { g.head = 0; g.head_time = 0; }
    else if (!strcmp(p, "--name")) { g.head = 1; g.head_time = 1; }
    else if (!strcmp(p, "--quiet") || !strcmp(p,"--silent")) g.verbosity = 0;
    else if (!strcmp(p, "--recursive")) g.recurse++;
    else if (!strcmp(p, "--rsyncable")) g.rsync = 1;
    else if (!strcmp(p, "--suffix")) g.sufx = get_string("--suffix");
    else if (!strcmp(p, "--test")) g.mode = OP_TEST;
    else if (!strcmp(p, "--verbose")) g.verbosity++;
    else if (!strcmp(p, "--version")) g.mode = OP_VERSION;
    else if (!strcmp(p, "--blocksize")) { unsigned long n = get_optnum("--blocksize");
        if (n < 32) abort_msg("block size too small (must be >= 32K)");
        if (n > 524288) abort_msg("block size too large: %lu", n);
        g.block = (size_t)n << 10; }
    else if (!strcmp(p, "--processes")) { unsigned long n = get_optnum("--processes");
        if (!n || n > 2147483647UL) abort_msg("invalid number of processes: %lu", n);
        g.procs = (int)n; }
    else if (!strcmp(p, "--alias")) g.alias = get_string("--alias");
    else if (!strcmp(p, "--comment")) g.comment = get_string("--comment");
    else if (!strcmp(p, "--first")) g.first = 1;
    else if (!strcmp(p, "--iterations")) g.iterations = (int)get_optnum("--iterations");
    else if (!strcmp(p, "--maxsplits")) g.maxsplits = (int)get_optnum("--maxsplits");
    else if (!strcmp(p, "--oneblock")) g.oneblock = 1;
    else if (!strcmp(p, "--synchronous")) g.sync = 1;
    else if (!strcmp(p, "--zlib")) g.form = 1;
    else if (!strcmp(p, "--zip")) g.form = 2;
    else abort_msg("invalid option: %s", oargv[optidx]);
    return 1;
}
static void parse_env(char *val) {
    char *copy = strdup(val), *p = strtok(copy, " \t");
    while (p) { if (p[0]=='-' && p[1]) { if (p[1]=='-') long_opt(p); else do_opt(p+1); } p = strtok(NULL," \t"); }
    free(copy);
}

static void list_date(char *buf, size_t n, long long mtime, int have_time)
{
    time_t t = (time_t)mtime, cur = time(NULL);
    struct tm lt, now;
    if (!have_time) { strcpy(buf, "------ -----"); return; }
    localtime_r(&t, &lt); localtime_r(&cur, &now);
    if (lt.tm_year == now.tm_year) strftime(buf, n, "%b %e %H:%M", &lt);
    else strftime(buf, n, "%b %e  %Y", &lt);
}

static void list_line(char *showname, long long mtime, int have_time, int method,
                      unsigned long check, int have_check, long long comp, long long orig)
{
    char datebuf[64]; double ratio;
    if (g.verbosity > 1) {
        const char *meth = g.form == 2 ? "zip" : (g.form == 1 ? "zlib" : "gzip");
        char chk[16];
        if (have_check) snprintf(chk, sizeof chk, "%08lx", check); else strcpy(chk, "--------");
        list_date(datebuf, sizeof datebuf, mtime, have_time);
        printf("%-4s %d  %s  %s ", meth, method, chk, datebuf);
    }
    if (orig > 0) {
        ratio = (orig - (double)comp) * 100.0 / (double)orig;
        printf("%10lld %10lld %6.1f%%  %s\n", comp, orig, ratio, showname);
    } else if (orig == 0)
        printf("%10lld %10lld %6s  %s\n", comp, orig, " -inf%", showname);
    else
        printf("%10lld %11s %4s    %s\n", comp, "0?", "unk", showname);
}

/* ---------- rsyncable ---------- */
static unsigned rsync_state;
static int rsync_match(unsigned char *buf, size_t len, size_t *endpos)
{
    size_t i; unsigned h = rsync_state;
    for (i = 0; i < len; i++) {
        h = ((h << 1) ^ buf[i]) & 0xffff;
        if ((h & 0xfff) == 0x7ff) { *endpos = i + 1; rsync_state = h; return 1; }
    }
    rsync_state = h; return 0;
}

static const unsigned char marker[5] = {0,0,0,0xff,0xff};

/* compress one pigz block */
static size_t deflate_block(z_stream *s, unsigned char *in, size_t len, int last,
                            unsigned char *out, size_t cap)
{
    int r; s->next_in = in; s->avail_in = (uInt)len;
    s->next_out = out; s->avail_out = (uInt)cap;
    if (last) {
        r = deflate(s, Z_FINISH);
        if (r != Z_STREAM_END) exit(1);
    } else {
        unsigned pend; int bits;
        deflate(s, Z_NO_FLUSH);
        r = deflate(s, Z_BLOCK);
        (void)r;
        deflatePending(s, &pend, &bits);
        int guard = 0;
        while (bits && guard < 20) {
            if (bits & 1) { deflate(s, Z_SYNC_FLUSH); deflate(s, Z_BLOCK); }
            else { deflate(s, Z_PARTIAL_FLUSH); deflate(s, Z_BLOCK); }
            deflatePending(s, &pend, &bits); guard++;
        }
    }
    return cap - s->avail_out;
}

/* ---------- gzip/zlib/zip headers ---------- */
static void put_gzip_header(FILE *out, char *name, long long mtime, int have_time)
{
    unsigned char hdr[10]; int flg = 0;
    if (g.head && name && !g.to_stdout) flg |= 8;
    hdr[0]=0x1f; hdr[1]=0x8b; hdr[2]=8; hdr[3]=(unsigned char)flg;
    if (g.head_time && have_time) {
        hdr[4]=(unsigned)(mtime&0xff); hdr[5]=(unsigned)((mtime>>8)&0xff);
        hdr[6]=(unsigned)((mtime>>16)&0xff); hdr[7]=(unsigned)((mtime>>24)&0xff);
    } else hdr[4]=hdr[5]=hdr[6]=hdr[7]=0;
    hdr[8] = (g.level == 1 || g.level == 11) ? 4 : (g.level == 9 ? 2 : 0);
    hdr[9] = 3;
    fwrite(hdr,1,10,out);
    if (flg & 8) fwrite(name,1,strlen(name)+1,out);
}
static void put_zlib_header(FILE *out)
{
    unsigned char hdr[2]; int lvl = g.level == 11 ? 9 : g.level;
    int cmf = 0x78, flg;
    flg = lvl >= 9 ? 0xda : (lvl >= 6 ? 0x9c : (lvl >= 1 ? 0x5e : 0x01));
    if (lvl == 1) flg = 0x01;
    hdr[0] = (unsigned char)cmf; hdr[1] = (unsigned char)flg;
    { int f = ((cmf << 8) | flg) % 31; if (f) flg += 31 - f; if (flg & 0x20) flg -= 31; }
    hdr[1] = (unsigned char)flg;
    fwrite(hdr,1,2,out);
}
static unsigned dos_time(long long mtime, int have_time)
{
    time_t t = have_time && g.head_time ? (time_t)mtime : time(NULL);
    struct tm lt; localtime_r(&t, &lt);
    return (unsigned)((lt.tm_hour << 11) | (lt.tm_min << 5) | (lt.tm_sec >> 1)) |
           (((unsigned)((lt.tm_year - 80) << 9) | ((lt.tm_mon+1) << 5) | lt.tm_mday) << 16);
}
static void put_zip_header(FILE *out, char *name, long long mtime, int have_time, size_t *hdrlen)
{
    unsigned char hdr[30]; unsigned dt = dos_time(mtime, have_time);
    size_t nl = 0;
    memset(hdr,0,sizeof hdr);
    if (g.alias) nl = strlen(g.alias); else if (g.head && name && !g.to_stdout) nl = strlen(name);
    hdr[0]='P'; hdr[1]='K'; hdr[2]=3; hdr[3]=4; hdr[4]=45; hdr[5]=0; hdr[6]=8; hdr[7]=0;
    hdr[8]=(unsigned char)(dt & 0xff); hdr[9]=(unsigned char)((dt>>8)&0xff);
    hdr[10]=(unsigned char)((dt>>16)&0xff); hdr[11]=(unsigned char)((dt>>24)&0xff);
    hdr[26]=(unsigned char)((20+nl)&0xff); hdr[27]=(unsigned char)((20+nl)>>8);
    hdr[28]=20; hdr[29]=0;
    fwrite(hdr,1,sizeof hdr,out);
    { unsigned char ex[20]; memset(ex,0,sizeof ex);
      ex[0]='U'; ex[1]='T'; ex[2]=5; ex[3]=0; ex[4]=1;
      if (g.head_time && have_time) { ex[5]=(unsigned)(mtime&0xff); ex[6]=(unsigned)((mtime>>8)&0xff);
        ex[7]=(unsigned)((mtime>>16)&0xff); ex[8]=(unsigned)((mtime>>24)&0xff); }
      ex[9]='U'; ex[10]='x'; fwrite(ex,1,20,out); }
    if (nl) fwrite(g.alias ? g.alias : name, 1, nl, out);
    *hdrlen = sizeof hdr + 20 + nl;
}

/* ---------- compress a stream ---------- */
static void compress_stream(FILE *in, FILE *out, char *name, long long mtime, int have_time)
{
    size_t cap = g.block + 65536 + 4096;
    unsigned char *inbuf = malloc(g.block + 1);
    unsigned char *outbuf = malloc(cap);
    unsigned char *dict = malloc(32768);
    size_t dictlen = 0; int have_dict = 0, first = 1;
    unsigned long crc = crc32(0L, Z_NULL, 0);
    unsigned long adler = adler32(0L, Z_NULL, 0);
    unsigned long long total = 0;
    z_stream s;

    if (g.form == 0) put_gzip_header(out, name, mtime, have_time);
    else if (g.form == 1) put_zlib_header(out);
    else { size_t hl; put_zip_header(out, name, mtime, have_time, &hl); }

    while (1) {
        size_t len = fread(inbuf, 1, g.block, in);
        int last = 0;
        if (len == 0) { if (ferror(in)) { skip_msg("read error"); exit(1); } break; }
        if (g.rsync && len > 0) { size_t ep; if (rsync_match(inbuf, len, &ep)) len = ep; }
        if (len < g.block && feof(in)) last = 1;
        memset(&s, 0, sizeof s);
        deflateInit2(&s, g.level == 11 ? 9 : g.level, Z_DEFLATED, -15, 8, g.strategy);
        if (!g.indep && have_dict) deflateSetDictionary(&s, dict, (uInt)dictlen);
        if (g.indep && !first) fwrite(marker, 1, 5, out);
        {
            size_t produced = deflate_block(&s, inbuf, len, last, outbuf, cap);
            fwrite(outbuf, 1, produced, out);
            crc = crc32(crc, inbuf, (uInt)len);
            adler = adler32(adler, inbuf, (uInt)len);
            total += len;
            if (len >= 32768) memcpy(dict, inbuf + len - 32768, 32768);
            else {
                size_t keep = dictlen > (32768 - len) ? 32768 - len : dictlen;
                memmove(dict, dict + (dictlen - keep), keep);
                memcpy(dict + keep, inbuf, len);
                dictlen = keep + len;
            }
            have_dict = 1; first = 0;
        }
        deflateEnd(&s);
        if (last) break;
    }
    free(inbuf); free(outbuf); free(dict);
    /* trailer */
    if (g.form == 0) {
        unsigned char tr[8];
        tr[0]=(unsigned char)(crc&0xff); tr[1]=(unsigned char)((crc>>8)&0xff);
        tr[2]=(unsigned char)((crc>>16)&0xff); tr[3]=(unsigned char)((crc>>24)&0xff);
        tr[4]=(unsigned char)(total&0xff); tr[5]=(unsigned char)((total>>8)&0xff);
        tr[6]=(unsigned char)((total>>16)&0xff); tr[7]=(unsigned char)((total>>24)&0xff);
        fwrite(tr,1,8,out);
    } else if (g.form == 1) {
        unsigned char tr[4];
        tr[0]=(unsigned char)(adler&0xff); tr[1]=(unsigned char)((adler>>8)&0xff);
        tr[2]=(unsigned char)((adler>>16)&0xff); tr[3]=(unsigned char)((adler>>24)&0xff);
        fwrite(tr,1,4,out);
    } else {
        /* zip data descriptor + central directory + end of central dir */
        unsigned char dd[16]; unsigned dt = dos_time(mtime, have_time);
        memset(dd,0,sizeof dd);
        dd[0]='P'; dd[1]='K'; dd[2]=7; dd[3]=8;
        dd[4]=(unsigned char)(crc&0xff); dd[5]=(unsigned char)((crc>>8)&0xff);
        dd[6]=(unsigned char)((crc>>16)&0xff); dd[7]=(unsigned char)((crc>>24)&0xff);
        /* compressed size is written by the caller? we approximate with ftell */
        fwrite(dd,1,16,out);
        /* central directory */
        {
            unsigned char cd[46]; size_t nl = 0;
            if (g.alias) nl = strlen(g.alias); else if (g.head && name && !g.to_stdout) nl = strlen(name);
            memset(cd,0,sizeof cd);
            cd[0]='P'; cd[1]='K'; cd[2]=1; cd[3]=2;
            cd[4]=45; cd[5]=0; cd[6]=45; cd[7]=0xff;
            cd[8]=8; cd[9]=0;
            cd[10]=(unsigned char)(dt&0xff); cd[11]=(unsigned char)((dt>>8)&0xff);
            cd[12]=(unsigned char)((dt>>16)&0xff); cd[13]=(unsigned char)((dt>>24)&0xff);
            cd[14]=(unsigned char)(crc&0xff); cd[15]=(unsigned char)((crc>>8)&0xff);
            cd[16]=(unsigned char)((crc>>16)&0xff); cd[17]=(unsigned char)((crc>>24)&0xff);
            cd[24]=(unsigned char)(total&0xff); cd[25]=(unsigned char)((total>>8)&0xff);
            cd[26]=(unsigned char)((total>>16)&0xff); cd[27]=(unsigned char)((total>>24)&0xff);
            cd[28]=(unsigned char)(nl&0xff); cd[29]=(unsigned char)((nl>>8)&0xff);
            cd[30]=20; cd[31]=0;
            fwrite(cd,1,sizeof cd,out);
            if (nl) fwrite(g.alias?g.alias:name,1,nl,out);
            { unsigned char ex[20]; memset(ex,0,sizeof ex);
              ex[0]='U'; ex[1]='T'; ex[2]=5; ex[3]=0; ex[4]=1;
              if (g.head_time && have_time) { ex[5]=(unsigned)(mtime&0xff); ex[6]=(unsigned)((mtime>>8)&0xff);
                ex[7]=(unsigned)((mtime>>16)&0xff); ex[8]=(unsigned)((mtime>>24)&0xff); }
              ex[9]='U'; ex[10]='x'; fwrite(ex,1,20,out); }
            /* end of central directory */
            unsigned char eocd[22]; memset(eocd,0,sizeof eocd);
            eocd[0]='P'; eocd[1]='K'; eocd[2]=5; eocd[3]=6; eocd[8]=1; eocd[9]=0;
            eocd[10]=1; eocd[11]=0;
            fwrite(eocd,1,sizeof eocd,out);
        }
    }
    if (g.verbosity) fprintf(stderr, "%s to %s \n", name ? name : "<stdin>",
                             g.to_stdout ? "<stdout>" : "");
}

/* ---------- decompress ---------- */
static int suffix_match(char *name, char **out)
{
    static const char *sufs[] = { ".gz", ".zz", ".zip", ".z", ".Z", ".ZIP", ".tgz", NULL };
    int i;
    for (i = 0; sufs[i]; i++) {
        size_t nl = strlen(name), ns = strlen(sufs[i]);
        if (nl > ns && strcmp(name + nl - ns, sufs[i]) == 0) {
            char *o = strndup(name, nl - ns);
            if (strcmp(sufs[i], ".tgz") == 0) { free(o); o = strndup(name, nl-4); o = realloc(o, nl-4+5); sprintf(o, "%.*s.tar", (int)(nl-4), name); }
            *out = o; return 1;
        }
    }
    return 0;
}

static void decompress_stream(FILE *in, FILE *out, char *inname)
{
    unsigned char hdr[16];
    int form = -1;
    size_t n;
    unsigned long crc_expect = 0, adler_expect = 0;
    unsigned long long isize = 0;
    int have_trailer = 0;
    unsigned long crc = crc32(0L, Z_NULL, 0);
    unsigned long adler = adler32(0L, Z_NULL, 0);
    unsigned long long total = 0;
    unsigned char *buf = malloc(1 << 16);
    unsigned char *outb = malloc(1 << 17);
    int member = 0;

    while (1) {
        n = fread(hdr, 1, 2, in);
        if (n == 0) break;
        if (n < 2) { skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
        if (hdr[0] == 0x1f && hdr[1] == 0x8b) {
            unsigned char h[10];
            h[0]=hdr[0]; h[1]=hdr[1];
            if (fread(h+2, 1, 8, in) != 8) { skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
            if (h[2] != 8) { skip_msg("%s unrecognized format", inname); exit(1); }
            int flg = h[3];
            if (flg & 4) { unsigned xl; if (fread(&xl,1,2,in)!=2) exit(1); fseek(in, xl, SEEK_CUR); }
            if (flg & 8) { int c; while ((c = getc(in)) != 0 && c != EOF) ; }
            if (flg & 16) { int c; while ((c = getc(in)) != 0 && c != EOF) ; }
            if (flg & 2) fseek(in, 2, SEEK_CUR);
            form = 0;
        } else if ((hdr[0] & 0x0f) == 8 && ((hdr[0] << 8) | hdr[1]) % 31 == 0) {
            form = 1;
        } else if (hdr[0] == 'P' && hdr[1] == 'K' && fgetc(in) == 3 && fgetc(in) == 4) {
            form = 2;
            fseek(in, 26, SEEK_CUR);
        } else { skip_msg("%s unrecognized format", inname); exit(1); }

        {
            z_stream s; int ret; int window = form == 0 ? 15 : (form == 1 ? 15 : -15);
            if (form == 0) window = 15 + 16; else if (form == 1) window = 15;
            memset(&s, 0, sizeof s);
            if (inflateInit2(&s, window) != Z_OK) exit(1);
            while (1) {
                if (s.avail_in == 0) {
                    size_t got = fread(buf, 1, 1 << 16, in);
                    if (got == 0) break;
                    s.next_in = buf; s.avail_in = (uInt)got;
                }
                s.next_out = outb; s.avail_out = 1 << 17;
                ret = inflate(&s, Z_NO_FLUSH);
                size_t prod = (1 << 17) - s.avail_out;
                if (prod) { fwrite(outb, 1, prod, out); crc = crc32(crc, outb, (uInt)prod);
                            adler = adler32(adler, outb, (uInt)prod); total += prod; }
                if (ret == Z_STREAM_END) break;
                if (ret != Z_OK) { inflateEnd(&s); free(buf); free(outb);
                    skip_msg("%s: corrupted -- invalid deflate data (%s)", inname, s.msg ? s.msg : "unknown");
                    exit(1); }
                if (s.avail_in == 0 && feof(in)) break;
            }
            inflateEnd(&s);
            if (ret != Z_STREAM_END) { free(buf); free(outb);
                skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
            /* trailer */
            if (form == 0) {
                unsigned char tr[8];
                if (s.avail_in >= 8) { memcpy(tr, s.next_in, 8); s.next_in += 8; s.avail_in -= 8; }
                else if (fread(tr, 1, 8, in) != 8) { free(buf); free(outb);
                    skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
                crc_expect = tr[0] | (tr[1]<<8) | ((unsigned long)tr[2]<<16) | ((unsigned long)tr[3]<<24);
                isize = tr[4] | (tr[5]<<8) | ((unsigned long long)tr[6]<<16) | ((unsigned long long)tr[7]<<24);
                have_trailer = 1;
            } else if (form == 1) {
                unsigned char tr[4];
                if (s.avail_in >= 4) { memcpy(tr, s.next_in, 4); s.next_in += 4; s.avail_in -= 4; }
                else if (fread(tr, 1, 4, in) != 4) { free(buf); free(outb);
                    skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
                adler_expect = tr[0] | (tr[1]<<8) | ((unsigned long)tr[2]<<16) | ((unsigned long)tr[3]<<24);
                have_trailer = 1;
            } else {
                /* zip: data descriptor */
                unsigned char tr[16];
                if (fread(tr,1,16,in) != 16) { free(buf); free(outb);
                    skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
                crc_expect = tr[4] | (tr[5]<<8) | ((unsigned long)tr[6]<<16) | ((unsigned long)tr[7]<<24);
                isize = tr[12] | (tr[13]<<8) | ((unsigned long long)tr[14]<<16) | ((unsigned long long)tr[15]<<24);
                have_trailer = 1;
            }
            member++;
            if (isize != total) { free(buf); free(outb);
                skip_msg("%s: corrupted -- length mismatch", inname); exit(1); }
            if (member == 1 && crc != crc_expect) { free(buf); free(outb);
                skip_msg("%s: corrupted -- crc32 mismatch", inname); exit(1); }
            if (form == 1 && adler != adler_expect) { free(buf); free(outb);
                skip_msg("%s: corrupted -- adler32 mismatch", inname); exit(1); }
            crc = crc32(0L, Z_NULL, 0); adler = adler32(0L, Z_NULL, 0); total = 0;
            /* more members? */
            if (s.avail_in > 0) { /* push back */
                /* copy remaining to the front of buf for the next member */
                memmove(buf, s.next_in, s.avail_in);
                /* emulate by seeking back: not possible on pipes; instead
                   continue the loop and re-read -- handle by re-checking header */
                /* simplest: exit the member loop with leftover data */
                fseek(in, -(long)s.avail_in, SEEK_CUR);
            }
            if (feof(in)) break;
        }
    }
    free(buf); free(outb);
}

/* ---------- listing ---------- */
static void list_stream(FILE *in, char *name, char *showname)
{
    unsigned char hdr[16]; size_t n;
    unsigned long crc = 0, adler = 0; long long comp = 0, orig = 0;
    long long mtime = 0; int have_time = 0, have_check = 0, have_orig = 0;
    int method = 8;
    n = fread(hdr, 1, 2, in);
    if (n < 2) { skip_msg("%s unrecognized format", name); exit(1); }
    if (hdr[0] == 0x1f && hdr[1] == 0x8b) {
        unsigned char h[10];
        h[0]=hdr[0]; h[1]=hdr[1];
        if (fread(h+2,1,8,in) != 8) { skip_msg("%s unrecognized format", name); exit(1); }
        int flg = h[3];
        mtime = h[4] | (h[5]<<8) | ((long long)h[6]<<16) | ((long long)h[7]<<24);
        have_time = (flg & 2) || (mtime != 0);
        if (flg & 4) { unsigned xl; if (fread(&xl,1,2,in)!=2) exit(1); fseek(in,xl,SEEK_CUR); }
        if (flg & 8) { int c; while ((c=getc(in))!=0 && c!=EOF) ; }
        if (flg & 16) { int c; while ((c=getc(in))!=0 && c!=EOF) ; }
        if (flg & 2) fseek(in,2,SEEK_CUR);
        /* inflate the rest to get the sizes and crc */
        { z_stream s; int ret; unsigned char *buf = malloc(1<<16), *outb = malloc(1<<17);
          memset(&s,0,sizeof s); inflateInit2(&s, 15+16);
          unsigned long long tot = 0;
          while (1) {
            if (s.avail_in == 0) { size_t got = fread(buf,1,1<<16,in); if (!got) break; s.next_in=buf; s.avail_in=(uInt)got; }
            s.next_out = outb; s.avail_out = 1<<17;
            ret = inflate(&s, Z_NO_FLUSH);
            size_t prod = (1<<17) - s.avail_out;
            tot += prod;
            if (ret == Z_STREAM_END) break;
            if (ret != Z_OK || (s.avail_in==0 && feof(in))) break;
          }
          comp = s.total_in + 10 + (flg&8 ? strlen(showname)+1 : 0);
          orig = (long long)tot;
          inflateEnd(&s); free(buf); free(outb);
          (void)n;
        }
        have_orig = 1;
        list_line(showname, mtime, have_time, method, crc, 0, comp, orig);
    } else if ((hdr[0] & 0x0f) == 8 && ((hdr[0]<<8)|hdr[1]) % 31 == 0) {
        /* zlib: unknown original */
        long long c = 2;
        fseek(in, 0, SEEK_END); long long fs = ftell(in);
        c = fs - 4;
        g.form = 1;
        list_line(showname, 0, 0, method, 0, 0, c, -1);
    } else if (hdr[0]=='P' && hdr[1]=='K' && fgetc(in)==3 && fgetc(in)==4) {
        g.form = 2;
        fseek(in, 0, SEEK_END); long long fs = ftell(in);
        fseek(in, -22, SEEK_END);
        list_line(showname, 0, 1, method, 0, 0, 0, -1);
    } else { skip_msg("%s unrecognized format", name); exit(1); }
}

/* ---------- file processing ---------- */
static void process(char *name, int is_dash);

static void recurse_dir(char *name)
{
    DIR *d = opendir(name);
    struct dirent *e;
    char *path;
    if (!d) { skip_msg("%s cannot be opened", name); return; }
    while ((e = readdir(d))) {
        if (!strcmp(e->d_name, ".") || !strcmp(e->d_name, "..")) continue;
        size_t nl = strlen(name), ne = strlen(e->d_name);
        path = malloc(nl + ne + 2);
        int need_slash = !(nl && name[nl-1] == '/');
        sprintf(path, "%s%s%s", name, need_slash ? "/" : "", e->d_name);
        process(path, 0);
        free(path);
    }
    closedir(d);
}

static void process(char *name, int is_dash)
{
    struct stat st;
    FILE *in, *out;
    char *outname = NULL, *showname = NULL;
    long long mtime = 0; int have_time = 0;

    if (is_dash) {
        in = stdin;
        if (g.mode == OP_COMPILE) {
            if (isatty(0) && !g.force) { skip_msg("<stdin> is a terminal"); return; }
            compress_stream(in, stdout, NULL, 0, 0);
        } else if (g.mode == OP_DECOMPRESS) {
            decompress_stream(in, stdout, "<stdin>");
        } else if (g.mode == OP_LIST) {
            list_stream(in, "<stdin>", "<stdin>");
        } else decompress_stream(in, stdout, "<stdin>");
        return;
    }
    if (g.recurse && stat(name, &st) == 0 && S_ISDIR(st.st_mode)) { recurse_dir(name); return; }
    if (lstat(name, &st)) { skip_msg("%s does not exist", name); return; }
    if (S_ISDIR(st.st_mode)) { skip_msg("%s is a directory", name); return; }
    if (S_ISLNK(st.st_mode) && !g.force) { skip_msg("%s is a symbolic link", name); return; }
    if (stat(name, &st)) { skip_msg("%s does not exist", name); return; }
    if (!S_ISREG(st.st_mode) && !g.force) { skip_msg("%s is a special file or device", name); return; }
    if (g.mode == OP_COMPILE && !(g.form == 2) && g.sufx && strlen(g.sufx) &&
        strlen(name) >= strlen(g.sufx) &&
        strcmp(name + strlen(name) - strlen(g.sufx), g.sufx) == 0 && !g.force) {
        skip_msg("%s ends with %s", name, g.sufx); return;
    }
    if (g.mode == OP_COMPILE) {
        const char *sfx = g.sufx ? g.sufx : (g.form == 1 ? ".zz" : (g.form == 2 ? ".zip" : ".gz"));
        outname = malloc(strlen(name) + strlen(sfx) + 1);
        sprintf(outname, "%s%s", name, sfx);
    } else if (g.mode == OP_DECOMPRESS) {
        if (!suffix_match(name, &outname)) { skip_msg("%s does not have compressed suffix", name); return; }
    } else outname = NULL;

    in = fopen(name, "rb");
    if (!in) { skip_msg("%s cannot be opened", name); return; }
    mtime = (long long)st.st_mtime; have_time = 1;
    if (g.mode == OP_LIST) {
        char *b = strdup(name); char *sl = strrchr(b, '/');
        showname = sl ? sl + 1 : b;
        if (g.mode == OP_LIST && !g.to_stdout) { }
        list_stream(in, name, showname);
        fclose(in); free(b);
        return;
    }
    if (g.to_stdout) out = stdout;
    else {
        if (!g.force && g.mode != OP_TEST) {
            struct stat ost;
            if (stat(outname, &ost) == 0) { skip_msg("%s exists", outname); fclose(in); return; }
        }
        out = fopen(outname, "wb");
        if (!out) { int e = errno; char buf[256]; snprintf(buf, sizeof buf, "write error on %s (%s)", outname, strerror(e)); if (g.verbosity) fprintf(stderr, "%s: abort: %s\n", prog, buf); exit(e); }
    }
    if (g.mode == OP_COMPILE) compress_stream(in, out, name, mtime, have_time);
    else decompress_stream(in, out, name);
    fclose(in);
    if (out != stdout) fclose(out);
    if (g.mode == OP_DECOMPRESS && g.head_time && have_time) {
        struct utimbuf ut; ut.actime = ut.modtime = (time_t)mtime; utime(outname, &ut);
    }
    if (!g.keep && !g.to_stdout && g.mode != OP_TEST) unlink(name);
    if (g.verbosity && g.mode != OP_LIST)
        fprintf(stderr, "%s to %s \n", name, g.to_stdout ? "<stdout>" : outname ? outname : "");
    free(outname);
}

int main(int argc, char **argv)
{
    int i;
    prog = strrchr(argv[0], '/');
    prog = prog ? prog + 1 : argv[0];
    memset(&g, 0, sizeof g);
    g.mode = OP_COMPILE;
    g.head = g.head_time = 1;
    g.level = 6; g.strategy = 0;
    g.block = 128 * 1024;
    g.iterations = 15; g.maxsplits = 15;
    g.verbosity = 1;
    { char *e = getenv("GZIP"); if (e) parse_env(e);
      e = getenv("PIGZ"); if (e) parse_env(e); }
    /* parse options */
    for (i = 1; i < argc; i++) {
        if (no_more_opts) break;
        if (argv[i][0] == '-' && argv[i][1]) {
            oargv = argv; oargc = argc; optidx = i;
            if (argv[i][1] == '-') long_opt(argv[i]);
            else { if (!do_opt(argv[i] + 1)) { no_more_opts = 1; break; } i = optidx; }
        } else break;
    }
    if (g.mode == OP_HELP) { fputs(usage_text, stderr); return 0; }
    if (g.mode == OP_LICENSE) {
        printf("pigz %s\nCopyright (C) 2007-2023 Mark Adler\n"
               "Subject to the terms of the zlib license.\n"
               "No warranty is provided or implied.\n", PIGZ_VERSION);
        return 0;
    }
    if (g.mode == OP_VERSION) {
        printf("pigz %s\n", PIGZ_VERSION);
        if (g.verbosity > 1) printf("zlib %s\n", zlibVersion());
        return 0;
    }
    if (g.sufx && !strlen(g.sufx)) abort_msg("suffix cannot be empty");
    /* process files */
    if (i >= argc) {
        process("-", 1);
    } else {
        int started = 0, listed = 0;
        for (; i < argc; i++) {
            if (!no_more_opts && !strcmp(argv[i], "-")) { process("-", 1); started = 1; continue; }
            process(argv[i], 0);
            if (g.mode == OP_LIST && !listed) { listed = 1;
                if (g.verbosity > 1) printf("method    check    timestamp    compressed   original reduced  name\n");
                else printf("compressed   original reduced  name\n");
            }
        }
        (void)started;
    }
    return errcnt ? 1 : 0;
}
