        dd[4]=(unsigned char)(crc&0xff); dd[5]=(unsigned char)((crc>>8)&0xff);
        dd[6]=(unsigned char)((crc>>16)&0xff); dd[7]=(unsigned char)((crc>>24)&0xff);
