            if (g.alias) nl = strlen(g.alias); else if (g.head && name && !g.to_stdout) nl = strlen(name);
            memset(cd,0,sizeof cd);
            cd[0]='P'; cd[1]='K'; cd[2]=1; cd[3]=2;
            cd[4]=45; cd[5]=0; cd[6]=45; cd[7]=0xff;
            cd[8]=8; cd[9]=0;
            cd[10]=(unsigned char)(dt&0xff); cd[11]=(unsigned char)((dt>>8)&0xff);
            cd[12]=(unsigned char)((dt>>16)&0xff); cd[13]=(unsigned char)((dt>>24)&0xff);
            cd[14]=(unsigned char)(crc&0xff); cd[15]=(unsigned char)((crc>>8)&0xff);
            cd[16]=(unsigned char)((crc>>16)&0xff); cd[17]=(unsigned char)((crc>>24)&0xff);
            cd[24]=(unsigned char)(total&0xff); cd[25]=(unsigned char)((total>>8)&0xff);
            cd[26]=(unsigned char)((total>>16)&0xff); cd[27]=(unsigned char)((total>>24)&0xff);
            cd[28]=(unsigned char)(nl&0xff); cd[29]=(unsigned char)((nl>>8)&0xff);
            cd[30]=20; cd[31]=0;
            fwrite(cd,1,sizeof cd,out);
            if (nl) fwrite(g.alias?g.alias:name,1,nl,out);
            { unsigned char ex[20]; memset(ex,0,sizeof ex);
              ex[0]='U'; ex[1]='T'; ex[2]=5; ex[3]=0; ex[4]=1;
              if (g.head_time && have_time) { ex[5]=(unsigned)(mtime&0xff); ex[6]=(unsigned)((mtime>>8)&0xff);
                ex[7]=(unsigned)((mtime>>16)&0xff); ex[8]=(unsigned)((mtime>>24)&0xff); }
              ex[9]='U'; ex[10]='x'; fwrite(ex,1,20,out); }
            /* end of central directory */
            unsigned char eocd[22]; memset(eocd,0,sizeof eocd);
            eocd[0]='P'; eocd[1]='K'; eocd[2]=5; eocd[3]=6; eocd[8]=1; eocd[9]=0;
            eocd[10]=1; eocd[11]=0;
            fwrite(eocd,1,sizeof eocd,out);
        }
    }
    if (g.verbosity) fprintf(stderr, "%s to %s \n", name ? name : "<stdin>",
                             g.to_stdout ? "<stdout>" : "");
}

/* ---------- decompress ---------- */
static int suffix_match(char *name, char **out)
{
    static const char *sufs[] = { ".gz", ".zz", ".zip", ".z", ".Z", ".ZIP", ".tgz", NULL };
    int i;
    for (i = 0; sufs[i]; i++) {
        size_t nl = strlen(name), ns = strlen(sufs[i]);
        if (nl > ns && strcmp(name + nl - ns, sufs[i]) == 0) {
            char *o = strndup(name, nl - ns);
            if (strcmp(sufs[i], ".tgz") == 0) { free(o); o = strndup(name, nl-4); o = realloc(o, nl-4+5); sprintf(o, "%.*s.tar", (int)(nl-4), name); }
            *out = o; return 1;
        }
    }
    return 0;
}

static void decompress_stream(FILE *in, FILE *out, char *inname)
{
    unsigned char hdr[16];
    int form = -1;
    size_t n;
    unsigned long crc_expect = 0, adler_expect = 0;
    unsigned long long isize = 0;
    int have_trailer = 0;
    unsigned long crc = crc32(0L, Z_NULL, 0);
    unsigned long adler = adler32(0L, Z_NULL, 0);
    unsigned long long total = 0;
    unsigned char *buf = malloc(1 << 16);
    unsigned char *outb = malloc(1 << 17);
    int member = 0;

    while (1) {
        n = fread(hdr, 1, 2, in);
        if (n == 0) break;
        if (n < 2) { skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
        if (hdr[0] == 0x1f && hdr[1] == 0x8b) {
            unsigned char h[10];
            h[0]=hdr[0]; h[1]=hdr[1];
            if (fread(h+2, 1, 8, in) != 8) { skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
            if (h[2] != 8) { skip_msg("%s unrecognized format", inname); exit(1); }
            int flg = h[3];
            if (flg & 4) { unsigned xl; if (fread(&xl,1,2,in)!=2) exit(1); fseek(in, xl, SEEK_CUR); }
            if (flg & 8) { int c; while ((c = getc(in)) != 0 && c != EOF) ; }
            if (flg & 16) { int c; while ((c = getc(in)) != 0 && c != EOF) ; }
            if (flg & 2) fseek(in, 2, SEEK_CUR);
            form = 0;
        } else if ((hdr[0] & 0x0f) == 8 && ((hdr[0] << 8) | hdr[1]) % 31 == 0) {
            form = 1;
        } else if (hdr[0] == 'P' && hdr[1] == 'K' && fgetc(in) == 3 && fgetc(in) == 4) {
            form = 2;
            fseek(in, 26, SEEK_CUR);
        } else { skip_msg("%s unrecognized format", inname); exit(1); }

        {
            z_stream s; int ret; int window = form == 0 ? 15 : (form == 1 ? 15 : -15);
            if (form == 0) window = 15 + 16; else if (form == 1) window = 15;
            memset(&s, 0, sizeof s);
            if (inflateInit2(&s, window) != Z_OK) exit(1);
            while (1) {
                if (s.avail_in == 0) {
                    size_t got = fread(buf, 1, 1 << 16, in);
                    if (got == 0) break;
                    s.next_in = buf; s.avail_in = (uInt)got;
                }
                s.next_out = outb; s.avail_out = 1 << 17;
                ret = inflate(&s, Z_NO_FLUSH);
                size_t prod = (1 << 17) - s.avail_out;
                if (prod) { fwrite(outb, 1, prod, out); crc = crc32(crc, outb, (uInt)prod);
                            adler = adler32(adler, outb, (uInt)prod); total += prod; }
                if (ret == Z_STREAM_END) break;
                if (ret != Z_OK) { inflateEnd(&s); free(buf); free(outb);
                    skip_msg("%s: corrupted -- invalid deflate data (%s)", inname, s.msg ? s.msg : "unknown");
                    exit(1); }
                if (s.avail_in == 0 && feof(in)) break;
            }
            inflateEnd(&s);
            if (ret != Z_STREAM_END) { free(buf); free(outb);
                skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
            /* trailer */
            if (form == 0) {
                unsigned char tr[8];
                if (s.avail_in >= 8) { memcpy(tr, s.next_in, 8); s.next_in += 8; s.avail_in -= 8; }
                else if (fread(tr, 1, 8, in) != 8) { free(buf); free(outb);
                    skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
                crc_expect = tr[0] | (tr[1]<<8) | ((unsigned long)tr[2]<<16) | ((unsigned long)tr[3]<<24);
                isize = tr[4] | (tr[5]<<8) | ((unsigned long long)tr[6]<<16) | ((unsigned long long)tr[7]<<24);
                have_trailer = 1;
            } else if (form == 1) {
                unsigned char tr[4];
                if (s.avail_in >= 4) { memcpy(tr, s.next_in, 4); s.next_in += 4; s.avail_in -= 4; }
                else if (fread(tr, 1, 4, in) != 4) { free(buf); free(outb);
                    skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
                adler_expect = tr[0] | (tr[1]<<8) | ((unsigned long)tr[2]<<16) | ((unsigned long)tr[3]<<24);
                have_trailer = 1;
            } else {
                /* zip: data descriptor */
                unsigned char tr[16];
                if (fread(tr,1,16,in) != 16) { free(buf); free(outb);
                    skip_msg("%s: corrupted -- missing trailer", inname); exit(1); }
                crc_expect = tr[4] | (tr[5]<<8) | ((unsigned long)tr[6]<<16) | ((unsigned long)tr[7]<<24);
                isize = tr[12] | (tr[13]<<8) | ((unsigned long long)tr[14]<<16) | ((unsigned long long)tr[15]<<24);
                have_trailer = 1;
            }
            member++;
            if (isize != total) { free(buf); free(outb);
                skip_msg("%s: corrupted -- length mismatch", inname); exit(1); }
            if (member == 1 && crc != crc_expect) { free(buf); free(outb);
                skip_msg("%s: corrupted -- crc32 mismatch", inname); exit(1); }
            if (form == 1 && adler != adler_expect) { free(buf); free(outb);
                skip_msg("%s: corrupted -- adler32 mismatch", inname); exit(1); }
            crc = crc32(0L, Z_NULL, 0); adler = adler32(0L, Z_NULL, 0); total = 0;
            /* more members? */
            if (s.avail_in > 0) { /* push back */
                /* copy remaining to the front of buf for the next member */
                memmove(buf, s.next_in, s.avail_in);
                /* emulate by seeking back: not possible on pipes; instead
                   continue the loop and re-read -- handle by re-checking header */
                /* simplest: exit the member loop with leftover data */
                fseek(in, -(long)s.avail_in, SEEK_CUR);
            }
            if (feof(in)) break;
        }
    }
    free(buf); free(outb);
}

/* ---------- listing ---------- */
static void list_stream(FILE *in, char *name, char *showname)
{
    unsigned char hdr[16]; size_t n;
    unsigned long crc = 0, adler = 0; long long comp = 0, orig = 0;
    long long mtime = 0; int have_time = 0, have_check = 0, have_orig = 0;
    int method = 8;
    n = fread(hdr, 1, 2, in);
    if (n < 2) { skip_msg("%s unrecognized format", name); exit(1); }
    if (hdr[0] == 0x1f && hdr[1] == 0x8b) {
        unsigned char h[10];
        h[0]=hdr[0]; h[1]=hdr[1];
        if (fread(h+2,1,8,in) != 8) { skip_msg("%s unrecognized format", name); exit(1); }
        int flg = h[3];
        mtime = h[4] | (h[5]<<8) | ((long long)h[6]<<16) | ((long long)h[7]<<24);
        have_time = (flg & 2) || (mtime != 0);
        if (flg & 4) { unsigned xl; if (fread(&xl,1,2,in)!=2) exit(1); fseek(in,xl,SEEK_CUR); }
        if (flg & 8) { int c; while ((c=getc(in))!=0 && c!=EOF) ; }
        if (flg & 16) { int c; while ((c=getc(in))!=0 && c!=EOF) ; }
        if (flg & 2) fseek(in,2,SEEK_CUR);
        /* inflate the rest to get the sizes and crc */
        { z_stream s; int ret; unsigned char *buf = malloc(1<<16), *outb = malloc(1<<17);
          memset(&s,0,sizeof s); inflateInit2(&s, 15+16);
          unsigned long long tot = 0;
          while (1) {
            if (s.avail_in == 0) { size_t got = fread(buf,1,1<<16,in); if (!got) break; s.next_in=buf; s.avail_in=(uInt)got; }
            s.next_out = outb; s.avail_out = 1<<17;
            ret = inflate(&s, Z_NO_FLUSH);
            size_t prod = (1<<17) - s.avail_out;
            tot += prod;
            if (ret == Z_STREAM_END) break;
            if (ret != Z_OK || (s.avail_in==0 && feof(in))) break;
          }
          comp = s.total_in + 10 + (flg&8 ? strlen(showname)+1 : 0);
          orig = (long long)tot;
          inflateEnd(&s); free(buf); free(outb);
          (void)n;
        }
        have_orig = 1;
        list_line(showname, mtime, have_time, method, crc, 0, comp, orig);
    } else if ((hdr[0] & 0x0f) == 8 && ((hdr[0]<<8)|hdr[1]) % 31 == 0) {
        /* zlib: unknown original */
        long long c = 2;
        fseek(in, 0, SEEK_END); long long fs = ftell(in);
        c = fs - 4;
        g.form = 1;
        list_line(showname, 0, 0, method, 0, 0, c, -1);
    } else if (hdr[0]=='P' && hdr[1]=='K' && fgetc(in)==3 && fgetc(in)==4) {
        g.form = 2;
        fseek(in, 0, SEEK_END); long long fs = ftell(in);
        fseek(in, -22, SEEK_END);
        list_line(showname, 0, 1, method, 0, 0, 0, -1);
    } else { skip_msg("%s unrecognized format", name); exit(1); }
}

/* ---------- file processing ---------- */
static void process(char *name, int is_dash);

static void recurse_dir(char *name)
{
    DIR *d = opendir(name);
    struct dirent *e;
    char *path;
    if (!d) { skip_msg("%s cannot be opened", name); return; }
    while ((e = readdir(d))) {
        if (!strcmp(e->d_name, ".") || !strcmp(e->d_name, "..")) continue;
        size_t nl = strlen(name), ne = strlen(e->d_name);
        path = malloc(nl + ne + 2);
        int need_slash = !(nl && name[nl-1] == '/');
        sprintf(path, "%s%s%s", name, need_slash ? "/" : "", e->d_name);
        process(path, 0);
        free(path);
    }
    closedir(d);
}

static void process(char *name, int is_dash)
{
    struct stat st;
    FILE *in, *out;
    char *outname = NULL, *showname = NULL;
    long long mtime = 0; int have_time = 0;

    if (is_dash) {
        in = stdin;
        if (g.mode == OP_COMPILE) {
            if (isatty(0) && !g.force) { skip_msg("<stdin> is a terminal"); return; }
            compress_stream(in, stdout, NULL, 0, 0);
        } else if (g.mode == OP_DECOMPRESS) {
            decompress_stream(in, stdout, "<stdin>");
        } else if (g.mode == OP_LIST) {
            list_stream(in, "<stdin>", "<stdin>");
        } else decompress_stream(in, stdout, "<stdin>");
        return;
    }
    if (g.recurse && stat(name, &st) == 0 && S_ISDIR(st.st_mode)) { recurse_dir(name); return; }
    if (lstat(name, &st)) { skip_msg("%s does not exist", name); return; }
    if (S_ISDIR(st.st_mode)) { skip_msg("%s is a directory", name); return; }
    if (S_ISLNK(st.st_mode) && !g.force) { skip_msg("%s is a symbolic link", name); return; }
    if (stat(name, &st)) { skip_msg("%s does not exist", name); return; }
    if (!S_ISREG(st.st_mode) && !g.force) { skip_msg("%s is a special file or device", name); return; }
    if (g.mode == OP_COMPILE && !(g.form == 2) && g.sufx && strlen(g.sufx) &&
        strlen(name) >= strlen(g.sufx) &&
        strcmp(name + strlen(name) - strlen(g.sufx), g.sufx) == 0 && !g.force) {
        skip_msg("%s ends with %s", name, g.sufx); return;
    }
    if (g.mode == OP_COMPILE) {
        const char *sfx = g.sufx ? g.sufx : (g.form == 1 ? ".zz" : (g.form == 2 ? ".zip" : ".gz"));
        outname = malloc(strlen(name) + strlen(sfx) + 1);
        sprintf(outname, "%s%s", name, sfx);
    } else if (g.mode == OP_DECOMPRESS) {
        if (!suffix_match(name, &outname)) { skip_msg("%s does not have compressed suffix", name); return; }
    } else outname = NULL;

    in = fopen(name, "rb");
    if (!in) { skip_msg("%s cannot be opened", name); return; }
    mtime = (long long)st.st_mtime; have_time = 1;
    if (g.mode == OP_LIST) {
        char *b = strdup(name); char *sl = strrchr(b, '/');
        showname = sl ? sl + 1 : b;
        if (g.mode == OP_LIST && !g.to_stdout) { }
        list_stream(in, name, showname);
        fclose(in); free(b);
        return;
    }
    if (g.to_stdout) out = stdout;
    else {
        if (!g.force && g.mode != OP_TEST) {
            struct stat ost;
            if (stat(outname, &ost) == 0) { skip_msg("%s exists", outname); fclose(in); return; }
        }
        out = fopen(outname, "wb");
        if (!out) { int e = errno; char buf[256]; snprintf(buf, sizeof buf, "write error on %s (%s)", outname, strerror(e)); if (g.verbosity) fprintf(stderr, "%s: abort: %s\n", prog, buf); exit(e); }
    }
    if (g.mode == OP_COMPILE) compress_stream(in, out, name, mtime, have_time);
    else decompress_stream(in, out, name);
    fclose(in);
    if (out != stdout) fclose(out);
    if (g.mode == OP_DECOMPRESS && g.head_time && have_time) {
        struct utimbuf ut; ut.actime = ut.modtime = (time_t)mtime; utime(outname, &ut);
    }
    if (!g.keep && !g.to_stdout && g.mode != OP_TEST) unlink(name);
    if (g.verbosity && g.mode != OP_LIST)
        fprintf(stderr, "%s to %s \n", name, g.to_stdout ? "<stdout>" : outname ? outname : "");
    free(outname);
}

int main(int argc, char **argv)
{
    int i;
    prog = strrchr(argv[0], '/');
    prog = prog ? prog + 1 : argv[0];
    memset(&g, 0, sizeof g);
    g.mode = OP_COMPILE;
    g.head = g.head_time = 1;
    g.level = 6; g.strategy = 0;
    g.block = 128 * 1024;
    g.iterations = 15; g.maxsplits = 15;
    g.verbosity = 1;
    { char *e = getenv("GZIP"); if (e) parse_env(e);
      e = getenv("PIGZ"); if (e) parse_env(e); }
    /* parse options */
    for (i = 1; i < argc; i++) {
        if (no_more_opts) break;
        if (argv[i][0] == '-' && argv[i][1]) {
            oargv = argv; oargc = argc; optidx = i;
            if (argv[i][1] == '-') long_opt(argv[i]);
            else { if (!do_opt(argv[i] + 1)) { no_more_opts = 1; break; } i = optidx; }
        } else break;
    }
    if (g.mode == OP_HELP) { fputs(usage_text, stderr); return 0; }
    if (g.mode == OP_LICENSE) {
        printf("pigz %s\nCopyright (C) 2007-2023 Mark Adler\n"
               "Subject to the terms of the zlib license.\n"
               "No warranty is provided or implied.\n", PIGZ_VERSION);
        return 0;
    }
    if (g.mode == OP_VERSION) {
        printf("pigz %s\n", PIGZ_VERSION);
        if (g.verbosity > 1) printf("zlib %s\n", zlibVersion());
        return 0;
    }
    if (g.sufx && !strlen(g.sufx)) abort_msg("suffix cannot be empty");
    /* process files */
    if (i >= argc) {
        process("-", 1);
    } else {
        int started = 0, listed = 0;
        for (; i < argc; i++) {
            if (!no_more_opts && !strcmp(argv[i], "-")) { process("-", 1); started = 1; continue; }
            process(argv[i], 0);
            if (g.mode == OP_LIST && !listed) { listed = 1;
                if (g.verbosity > 1) printf("method    check    timestamp    compressed   original reduced  name\n");
                else printf("compressed   original reduced  name\n");
            }
        }
        (void)started;
    }
    return errcnt ? 1 : 0;
}
